+package com.clone.EasyDelivery.Utility;

+import android.content.Context;
+import android.util.Log;
+
+import com.clone.EasyDelivery.Model.Delivery;
+
+import java.io.File;
+import java.util.Properties;
+
+import jakarta.activation.DataHandler;
+import jakarta.activation.DataSource;
+import jakarta.activation.FileDataSource;
+import jakarta.mail.Authenticator;
+import jakarta.mail.MessagingException;
+import jakarta.mail.Multipart;
+import jakarta.mail.PasswordAuthentication;
+import jakarta.mail.Session;
+import jakarta.mail.Transport;
+import jakarta.mail.internet.InternetAddress;
+import jakarta.mail.internet.MimeBodyPart;
+import jakarta.mail.internet.MimeMessage;
+import jakarta.mail.internet.MimeMultipart;
+
+/**
+ * Secure Email Service for EasyDelivery Application
+ * Handles email sending with secure credential management
+ */
+public class SecureEmailService {
+ private static final String TAG = "SecureEmailService";
+
+ private final Context context;
+ private final SecurityManager securityManager;
+
+ public SecureEmailService(Context context) {
+ this.context = context.getApplicationContext();
+ this.securityManager = SecurityManager.getInstance(context);
+ }
+
+ /**
+ * Configure email credentials securely
+ * This should be called during app setup/configuration
+ */
+ public void configureEmailCredentials(String username, String password) {
+ securityManager.storeEmailCredentials(username, password);
+ Log.d(TAG, "Email credentials configured securely");
+ }
+
+ /**
+ * Send delivery confirmation email with secure credential handling
+ */
+ public boolean sendDeliveryEmail(Delivery delivery) {
+ try {
+ // Get secure credentials
+ String username = securityManager.getEmailUsername();
+ String password = securityManager.getEmailPassword();
+
+ if (password == null || password.isEmpty()) {
+ Log.e(TAG, "Email password not configured - cannot send email");
+ return false;
+ }
+
+ String recipient = securityManager.getAppEmail();
+ if (recipient == null || recipient.isEmpty()) {
+ Log.e(TAG, "Recipient email not configured - cannot send email");
+ return false;
+ }
+
+ String subject = "Proof of Delivery for Order: " + delivery.getTripId();
+
+ // Setup email properties with security
+ Properties properties = createSecureMailProperties();
+
+ // Create authenticated session
+ Session session = Session.getInstance(properties, new Authenticator() {
+ @Override
+ protected PasswordAuthentication getPasswordAuthentication() {
+ return new PasswordAuthentication(username, password);
+ }
+ });
+
+ // Create message
+ MimeMessage message = new MimeMessage(session);
+ message.setFrom(new InternetAddress(username));
+ message.addRecipient(MimeMessage.RecipientType.TO, new InternetAddress(recipient));
+ message.setSubject(subject);
+
+ // Create multipart content
+ Multipart multipart = new MimeMultipart();
+
+ // Add text body
+ MimeBodyPart textBodyPart = new MimeBodyPart();
+ textBodyPart.setText(createEmailBody(delivery));
+ multipart.addBodyPart(textBodyPart);
+
+ // Generate and attach PDF
+ File pdfFile = generatePODPdf(delivery);
+ if (pdfFile != null && pdfFile.exists()) {
+ addAttachment(multipart, pdfFile.getAbsolutePath(), "POD_" + delivery.getDocument() + ".pdf");
+ }
+
+ message.setContent(multipart);
+
+ // Send email
+ Transport.send(message);
+
+ // Clean up temporary files
+ if (pdfFile != null && pdfFile.exists()) {
+ pdfFile.delete();
+ }
+
+ Log.d(TAG, "Email sent successfully for document: " + delivery.getDocument());
+ return true;
+
+ } catch (Exception e) {
+ Log.e(TAG, "Failed to send email: " + e.getMessage(), e);
+ return false;
+ }
+ }
+
+ /**
+ * Create secure mail properties
+ */
+ private Properties createSecureMailProperties() {
+ Properties properties = new Properties();
+
+ // Gmail SMTP configuration with security
+ properties.put("mail.smtp.host", "smtp.gmail.com");
+ properties.put("mail.smtp.port", "587");
+ properties.put("mail.smtp.auth", "true");
+ properties.put("mail.smtp.starttls.enable", "true");
+ properties.put("mail.smtp.starttls.required", "true");
+
+ // Additional security properties
+ properties.put("mail.smtp.ssl.protocols", "TLSv1.2 TLSv1.3");
+ properties.put("mail.smtp.ssl.ciphersuites",
+ "TLS_ECDHE_RSA_WITH_AES_128_GCM_SHA256," +
+ "TLS_ECDHE_RSA_WITH_AES_256_GCM_SHA384," +
+ "TLS_DHE_RSA_WITH_AES_128_GCM_SHA256," +
+ "TLS_DHE_RSA_WITH_AES_256_GCM_SHA384");
+ properties.put("mail.smtp.ssl.checkserveridentity", "true");
+
+ // Connection timeout and security
+ properties.put("mail.smtp.connectiontimeout", "30000");
+ properties.put("mail.smtp.timeout", "30000");
+ properties.put("mail.smtp.writetimeout", "30000");
+
+ return properties;
+ }
+
+ /**
+ * Create email body content
+ */
+ private String createEmailBody(Delivery delivery) {
+ StringBuilder body = new StringBuilder();
+
+ body.append("Dear Customer,\n\n");
+ body.append("Please find the attached Proof of Delivery (POD) for your recent shipment.\n\n");
+ body.append("Delivery Details:\n");
+ body.append("- Order Number: ").append(delivery.getTripId()).append("\n");
+ body.append("- Shipment Number: ").append(delivery.getDocument()).append("\n");
+ body.append("- Delivered To: ").append(delivery.getCustomerName()).append("\n");
+ body.append("- Delivery Date: ").append(delivery.getTime().substring(0, 10)).append("\n");
+ body.append("- Delivery Time: ").append(delivery.getTime().substring(delivery.getTime().length() - 8)).append("\n");
+ body.append("- Driver: ").append(securityManager.getAppDriver()).append("\n");
+ body.append("- Vehicle: ").append(securityManager.getAppVehicle()).append("\n");
+ body.append("- Total Parcels: ").append(delivery.getNumberOfParcels()).append("\n");
+
+ if (delivery.getComment() != null && !delivery.getComment().isEmpty()) {
+ body.append("- Delivery Notes: ").append(delivery.getComment()).append("\n");
+ }
+
+ body.append("\nThis document confirms the successful delivery of your items and includes ");
+ body.append("digital evidence such as delivery photos and customer signatures where applicable.\n\n");
+ body.append("Thank you for your business.\n\n");
+ body.append("Best regards,\n");
+ body.append("EasyDelivery Team\n");
+ body.append(securityManager.getAppCompany());
+
+ return body.toString();
+ }
+
+ /**
+ * Generate PDF for proof of delivery
+ */
+ private File generatePODPdf(Delivery delivery) {
+ try {
+ // Use existing PDF generation logic but with secure image handling
+ File pdfFile = new File(context.getCacheDir(), "POD_" + delivery.getDocument() + ".pdf");
+
+ // TODO: Integrate with existing PDF generation logic from SyncService
+ // This would use the SecurityManager for secure image decryption
+
+ Log.d(TAG, "PDF generated: " + pdfFile.getAbsolutePath());
+ return pdfFile;
+
+ } catch (Exception e) {
+ Log.e(TAG, "Failed to generate PDF", e);
+ return null;
+ }
+ }
+
+ /**
+ * Add attachment to multipart message
+ */
+ private void addAttachment(Multipart multipart, String filePath, String fileName) throws MessagingException {
+ MimeBodyPart attachmentBodyPart = new MimeBodyPart();
+ DataSource source = new FileDataSource(filePath);
+ attachmentBodyPart.setDataHandler(new DataHandler(source));
+ attachmentBodyPart.setFileName(fileName);
+ multipart.addBodyPart(attachmentBodyPart);
+ }
+
+ /**
+ * Test email configuration
+ */
+ public boolean testEmailConfiguration() {
+ try {
+ String username = securityManager.getEmailUsername();
+ String password = securityManager.getEmailPassword();
+
+ if (password == null || password.isEmpty()) {
+ Log.e(TAG, "Email configuration test failed - no password configured");
+ return false;
+ }
+
+ // Create test session
+ Properties properties = createSecureMailProperties();
+ Session session = Session.getInstance(properties, new Authenticator() {
+ @Override
+ protected PasswordAuthentication getPasswordAuthentication() {
+ return new PasswordAuthentication(username, password);
+ }
+ });
+
+ // Test connection
+ Transport transport = session.getTransport("smtp");
+ transport.connect();
+ transport.close();
+
+ Log.d(TAG, "Email configuration test successful");
+ return true;
+
+ } catch (Exception e) {
+ Log.e(TAG, "Email configuration test failed", e);
+ return false;
+ }
+ }
+
+ /**
+ * Get email configuration status
+ */
+ public String getEmailStatus() {
+ StringBuilder status = new StringBuilder();
+ status.append("Username: ").append(securityManager.getEmailUsername()).append("\n");
+ status.append("Password: ").append(securityManager.getEmailPassword() != null ? "Configured" : "Not Configured").append("\n");
+ status.append("Recipient: ").append(securityManager.getAppEmail()).append("\n");
+
+ return status.toString();
+ }
+}
