import androidx.work.ExistingWorkPolicy;
import androidx.work.NetworkType;
import androidx.work.OneTimeWorkRequest;
import androidx.work.PeriodicWorkRequest;
import androidx.work.WorkManager;
import androidx.work.Worker;
import androidx.work.WorkerParameters;

import com.clone.EasyDelivery.sync.models.SyncResult;

import java.util.concurrent.TimeUnit;

/**
 * Background worker for performing synchronization operations
 * Uses WorkManager for reliable background execution with proper constraints
 */
public class SyncWorker extends Worker {

 private static final String TAG = "SyncWorker";

 // Work tags and names
 public static final String WORK_TAG_SYNC = "sync_work";
 public static final String WORK_NAME_PERIODIC_SYNC = "periodic_sync";
 public static final String WORK_NAME_IMMEDIATE_SYNC = "immediate_sync";

 // Work parameters
 private static final String KEY_SYNC_TYPE = "sync_type";
 private static final String KEY_FORCE_SYNC = "force_sync";

 // Sync types
 public static final String SYNC_TYPE_FULL = "full";
 public static final String SYNC_TYPE_PARTIAL = "partial";
 public static final String SYNC_TYPE_OFFLINE_ACTIONS = "offline_actions";

 // Timing configuration
 private static final long PERIODIC_SYNC_INTERVAL_MINUTES = 30; // 30 minutes
 private static final long FLEX_INTERVAL_MINUTES = 10; // Allow 10 minute flex
 private static final long IMMEDIATE_SYNC_DELAY_SECONDS = 5; // 5 second delay for immediate sync

 // Injected dependencies
 private final SyncManager syncManager;

 public SyncWorker(
 @NonNull Context context, 
 @NonNull WorkerParameters workerParams,
 SyncManager syncManager
 ) {
 super(context, workerParams);
 this.syncManager = syncManager;
 }

 @NonNull
 @Override
 public Result doWork() {
 Log.i(TAG, "SyncWorker started");

 try {
 // Get work parameters
 String syncType = getInputData().getString(KEY_SYNC_TYPE);
 boolean forceSync = getInputData().getBoolean(KEY_FORCE_SYNC, false);

 Log.d(TAG, "Performing sync - Type: " + syncType + ", Force: " + forceSync);

 // Perform the appropriate sync operation
 SyncResult result;
 switch (syncType != null ? syncType : SYNC_TYPE_FULL) {
 case SYNC_TYPE_FULL:
 result = performFullSync();
 break;
 case SYNC_TYPE_PARTIAL:
 result = performPartialSync();
 break;
 case SYNC_TYPE_OFFLINE_ACTIONS:
 result = performOfflineActionsSync();
 break;
 default:
 Log.w(TAG, "Unknown sync type: " + syncType + ", defaulting to full sync");
 result = performFullSync();
 break;
 }

 // Process result
 if (result.isSuccess()) {
 Log.i(TAG, "Sync completed successfully: " + result.getSummary());
 return Result.success(createOutputData(result));
 } else if (result.isPartialSuccess()) {
 Log.w(TAG, "Sync completed with warnings: " + result.getSummary());
 return Result.success(createOutputData(result));
 } else {
 Log.e(TAG, "Sync failed: " + result.getErrorMessage());
 return Result.retry(); // Retry on failure
 }

 } catch (Exception e) {
 Log.e(TAG, "SyncWorker failed with exception", e);
 return Result.retry(); // Retry on exception
 }
 }

 /**
 * Perform a full synchronization using SyncManager
 */
 private SyncResult performFullSync() {
 try {
 Log.d(TAG, "Starting full sync with SyncManager");

 // Use SyncManager for centralized sync operations
 SyncResult result = syncManager.performFullSync().get();

 Log.d(TAG, "Full sync completed: " + result.getSummary());
 return result;

 } catch (Exception e) {
 Log.e(TAG, "Full sync failed", e);
 return SyncResult.error("Full sync failed: " + e.getMessage());
 }
 }

 /**
 * Perform a partial synchronization (only urgent items)
 */
 private SyncResult performPartialSync() {
 try {
 Log.d(TAG, "Starting partial sync with SyncManager");

 // For partial sync, we'll use the full sync but it could be optimized
 // to only sync recent/urgent changes in the future
 SyncResult result = syncManager.performFullSync().get();

 Log.d(TAG, "Partial sync completed: " + result.getSummary());
 return result;

 } catch (Exception e) {
 Log.e(TAG, "Partial sync failed", e);
 return SyncResult.error("Partial sync failed: " + e.getMessage());
 }
 }

 /**
 * Perform offline actions sync only
 */
 private SyncResult performOfflineActionsSync() {
 try {
 Log.d(TAG, "Starting offline actions sync with SyncManager");

 // Process only offline actions without full sync
 // For now, use full sync but this could be optimized to process
 // only the offline actions queue in the future
 SyncResult result = syncManager.performFullSync().get();

 Log.d(TAG, "Offline actions sync completed: " + result.getSummary());
 return result;

 } catch (Exception e) {
 Log.e(TAG, "Offline actions sync failed", e);
 return SyncResult.error("Offline actions sync failed: " + e.getMessage());
 }
 }

 /**
 * Create output data with sync results
 */
 private Data createOutputData(SyncResult result) {
 return new Data.Builder()
 .putBoolean("success", result.isSuccess())
 .putBoolean("partial_success", result.isPartialSuccess())
 .putString("message", result.getMessage())
 .putString("error_message", result.getErrorMessage())
 .putInt("synced_count", result.getSyncedCount())
 .putLong("timestamp", result.getTimestamp())
 .build();
 }

 // =================== STATIC SCHEDULER METHODS ===================

 /**
 * Schedule periodic background sync
 */
 public static void schedulePeriodicSync(Context context) {
 Log.i(TAG, "Scheduling periodic sync every " + PERIODIC_SYNC_INTERVAL_MINUTES + " minutes");

 // Create constraints - only run with network and when not in doze mode
 Constraints constraints = new Constraints.Builder()
 .setRequiredNetworkType(NetworkType.CONNECTED)
 .setRequiresBatteryNotLow(true)
 .build();

 // Create input data
 Data inputData = new Data.Builder()
 .putString(KEY_SYNC_TYPE, SYNC_TYPE_FULL)
 .putBoolean(KEY_FORCE_SYNC, false)
 .build();

 // Create periodic work request
 PeriodicWorkRequest periodicWork = new PeriodicWorkRequest.Builder(
 SyncWorker.class,
 PERIODIC_SYNC_INTERVAL_MINUTES,
 TimeUnit.MINUTES,
 FLEX_INTERVAL_MINUTES,
 TimeUnit.MINUTES)
 .setConstraints(constraints)
 .setInputData(inputData)
 .addTag(WORK_TAG_SYNC)
 .build();

 // Schedule the work
 WorkManager.getInstance(context).enqueueUniquePeriodicWork(
 WORK_NAME_PERIODIC_SYNC,
 ExistingPeriodicWorkPolicy.KEEP, // Keep existing if already scheduled
 periodicWork
 );

 Log.d(TAG, "Periodic sync scheduled with ID: " + periodicWork.getId());
 }

 /**
 * Schedule immediate one-time sync
 */
 public static void scheduleImmediateSync(Context context, String syncType, boolean forceSync) {
 Log.i(TAG, "Scheduling immediate sync - Type: " + syncType + ", Force: " + forceSync);

 // Create constraints - require network
 Constraints constraints = new Constraints.Builder()
 .setRequiredNetworkType(NetworkType.CONNECTED)
 .build();

 // Create input data
 Data inputData = new Data.Builder()
 .putString(KEY_SYNC_TYPE, syncType)
 .putBoolean(KEY_FORCE_SYNC, forceSync)
 .build();

 // Create one-time work request with short delay
 OneTimeWorkRequest immediateWork = new OneTimeWorkRequest.Builder(SyncWorker.class)
 .setConstraints(constraints)
 .setInputData(inputData)
 .setInitialDelay(IMMEDIATE_SYNC_DELAY_SECONDS, TimeUnit.SECONDS)
 .addTag(WORK_TAG_SYNC)
 .build();

 // Schedule the work
 WorkManager.getInstance(context).enqueueUniqueWork(
 WORK_NAME_IMMEDIATE_SYNC,
 ExistingWorkPolicy.REPLACE, // Replace any existing immediate sync
 immediateWork
 );

 Log.d(TAG, "Immediate sync scheduled with ID: " + immediateWork.getId());
 }

 /**
 * Schedule sync when network becomes available
 */
 public static void scheduleNetworkSync(Context context) {
 Log.i(TAG, "Scheduling network-available sync");

 // Create constraints - only network requirement
 Constraints constraints = new Constraints.Builder()
 .setRequiredNetworkType(NetworkType.CONNECTED)
 .build();

 // Create input data for offline actions sync (most urgent)
 Data inputData = new Data.Builder()
 .putString(KEY_SYNC_TYPE, SYNC_TYPE_OFFLINE_ACTIONS)
 .putBoolean(KEY_FORCE_SYNC, false)
 .build();

 // Create one-time work request
 OneTimeWorkRequest networkWork = new OneTimeWorkRequest.Builder(SyncWorker.class)
 .setConstraints(constraints)
 .setInputData(inputData)
 .addTag(WORK_TAG_SYNC)
 .build();

 // Schedule the work
 WorkManager.getInstance(context).enqueue(networkWork);

 Log.d(TAG, "Network sync scheduled with ID: " + networkWork.getId());
 }

 /**
 * Cancel all scheduled sync work
 */
 public static void cancelAllSyncWork(Context context) {
 Log.i(TAG, "Cancelling all sync work");

 WorkManager workManager = WorkManager.getInstance(context);

 // Cancel by tag
 workManager.cancelAllWorkByTag(WORK_TAG_SYNC);

 // Cancel unique work
 workManager.cancelUniqueWork(WORK_NAME_PERIODIC_SYNC);
 workManager.cancelUniqueWork(WORK_NAME_IMMEDIATE_SYNC);

 Log.d(TAG, "All sync work cancelled");
 }

 /**
 * Cancel only periodic sync (keep immediate syncs)
 */
 public static void cancelPeriodicSync(Context context) {
 Log.i(TAG, "Cancelling periodic sync");

 WorkManager.getInstance(context).cancelUniqueWork(WORK_NAME_PERIODIC_SYNC);

 Log.d(TAG, "Periodic sync cancelled");
 }

