 Picasso.with(this)

 //bytearray converted to bitmap and bitmap converted to uri
 .load("file://"+AppConstants.ZOOM)
 .into(ivZoom); //this is your ImageView



 ivClose.setOnClickListener(new View.OnClickListener() {
 @Override
 public void onClick(View v) {

 finish();
 }
 });
 }
}
