 break;
 case ERROR:
 Log.w(TAG, "Error loading trip: " + resource.getMessage());
 currentTripStateLiveData.postValue(UiState.error(resource.getMessage()));
 break;
 case LOADING:
 // Keep current loading state
 break;
 }
 }
 });
 }
