import android.util.Log;

import com.clone.EasyDelivery.api.services.DeliveryService;
import com.clone.EasyDelivery.api.services.TripService;
import com.clone.EasyDelivery.data.dao.DeliveryDao;
import com.clone.EasyDelivery.data.dao.OfflineActionDao;
import com.clone.EasyDelivery.data.dao.TripDao;
import com.clone.EasyDelivery.data.entities.DeliveryEntity;
import com.clone.EasyDelivery.data.entities.OfflineActionEntity;
import com.clone.EasyDelivery.data.entities.TripEntity;
import com.clone.EasyDelivery.sync.models.SyncResult;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.atomic.AtomicInteger;

import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Processor for handling queued offline actions with batch processing and retry logic
 * Processes CRUD operations that were performed while offline and need to be synced
 */
@Singleton
public class OfflineActionProcessor {

 private static final String TAG = "OfflineActionProcessor";

 // Configuration
 private static final int MAX_RETRY_ATTEMPTS = 3;
 private static final int BATCH_SIZE = 10;
 private static final long RETRY_DELAY_MS = 2000; // 2 seconds

 // Dependencies injected by Hilt
 private final OfflineActionDao offlineActionDao;
 private final TripDao tripDao;
 private final DeliveryDao deliveryDao;
 private final TripService tripService;
 private final DeliveryService deliveryService;
 private final ExecutorService executorService;

 @Inject
 public OfflineActionProcessor(OfflineActionDao offlineActionDao,
 TripDao tripDao,
 DeliveryDao deliveryDao,
 TripService tripService,
 DeliveryService deliveryService,
 ExecutorService executorService) {
 this.offlineActionDao = offlineActionDao;
 this.tripDao = tripDao;
 this.deliveryDao = deliveryDao;
 this.tripService = tripService;
 this.deliveryService = deliveryService;
 this.executorService = executorService;

 Log.i(TAG, "OfflineActionProcessor initialized with Hilt DI");
 }

 /**
 * Process all pending offline actions in batches
 */
 public CompletableFuture<SyncResult> processAllPendingActions() {
 return CompletableFuture.supplyAsync(() -> {
 Log.i(TAG, "Starting batch processing of offline actions");

 try {
 List<OfflineActionEntity> pendingActions = offlineActionDao.getPendingActions();
 Log.d(TAG, "Found " + pendingActions.size() + " pending actions");

 if (pendingActions.isEmpty()) {
 return SyncResult.success("No offline actions to process", 0);
 }

 // Process actions in batches
 List<List<OfflineActionEntity>> batches = createBatches(pendingActions, BATCH_SIZE);
 AtomicInteger totalProcessed = new AtomicInteger(0);
 List<String> errors = new ArrayList<>();

 for (int i = 0; i < batches.size(); i++) {
 List<OfflineActionEntity> batch = batches.get(i);
 Log.d(TAG, "Processing batch " + (i + 1) + "/" + batches.size() + " (" + batch.size() + " actions)");

 SyncResult batchResult = processBatch(batch);
 totalProcessed.addAndGet(batchResult.getSyncedCount());

 if (batchResult.hasErrors()) {
 errors.addAll(batchResult.getErrors());
 }

 // Small delay between batches to avoid overwhelming the server
 if (i < batches.size() - 1) {
 try {
 Thread.sleep(500);
 } catch (InterruptedException e) {
 Thread.currentThread().interrupt();
 break;
 }
 }
 }

 // Return final result
 if (errors.isEmpty()) {
 Log.i(TAG, "All offline actions processed successfully: " + totalProcessed.get());
 return SyncResult.success("All offline actions processed", totalProcessed.get());
 } else {
 Log.w(TAG, "Some offline actions failed: " + errors.size() + " errors");
 return SyncResult.partialSuccess("Some actions failed", totalProcessed.get(), errors);
 }

 } catch (Exception e) {
 Log.e(TAG, "Failed to process offline actions", e);
 return SyncResult.error("Failed to process offline actions: " + e.getMessage());
 }
 }, executorService);
 }

 /**
 * Process a single batch of offline actions
 */
 private SyncResult processBatch(List<OfflineActionEntity> batch) {
 AtomicInteger processed = new AtomicInteger(0);
 List<String> errors = new ArrayList<>();

 for (OfflineActionEntity action : batch) {
 try {
 boolean success = processAction(action);
 if (success) {
 // Mark action as completed
 offlineActionDao.markActionCompleted(action.getId(), System.currentTimeMillis());
 processed.incrementAndGet();
 Log.d(TAG, "Successfully processed action: " + action.getActionType() + " for " + action.getEntityType());
 } else {
 handleActionFailure(action, "Action processing failed");
 errors.add("Failed to process " + action.getActionType() + " for " + action.getEntityType());
 }
 } catch (Exception e) {
 Log.e(TAG, "Exception processing action " + action.getId(), e);
 handleActionFailure(action, e.getMessage());
 errors.add("Exception processing " + action.getActionType() + ": " + e.getMessage());
 }
 }

 if (errors.isEmpty()) {
 return SyncResult.success("Batch processed successfully", processed.get());
 } else {
 return SyncResult.partialSuccess("Batch processed with errors", processed.get(), errors);
 }
 }

 /**
 * Process a single offline action
 */
 private boolean processAction(OfflineActionEntity action) {
 Log.d(TAG, "Processing action: " + action.getActionType() + " for " + action.getEntityType() + " " + action.getEntityId());

 switch (action.getEntityType()) {
 case "TRIP":
 return processTripAction(action);
 case "DELIVERY":
 return processDeliveryAction(action);
 default:
 Log.w(TAG, "Unknown entity type: " + action.getEntityType());
 return false;
 }
 }

 /**
 * Process trip-related offline actions
 */
 private boolean processTripAction(OfflineActionEntity action) {
 try {
 switch (action.getActionType()) {
 case "CREATE":
 case "UPDATE":
 TripEntity trip = tripDao.getTrip(action.getEntityId());
 if (trip == null) {
 Log.w(TAG, "Trip not found for action: " + action.getEntityId());
 return false;
 }
 return uploadTrip(trip);

 case "DELETE":
 return deleteTripOnServer(action.getEntityId());

 case "START":
 return startTripOnServer(action.getEntityId());

 case "COMPLETE":
 return completeTripOnServer(action.getEntityId());

 default:
 Log.w(TAG, "Unknown trip action: " + action.getActionType());
 return false;
 }
 } catch (Exception e) {
 Log.e(TAG, "Error processing trip action", e);
 return false;
 }
 }

 /**
 * Process delivery-related offline actions
 */
 private boolean processDeliveryAction(OfflineActionEntity action) {
 try {
 switch (action.getActionType()) {
 case "CREATE":
 case "UPDATE":
 DeliveryEntity delivery = deliveryDao.getDelivery(action.getEntityId());
 if (delivery == null) {
 Log.w(TAG, "Delivery not found for action: " + action.getEntityId());
 return false;
 }
 return uploadDelivery(delivery);

 case "DELETE":
 return deleteDeliveryOnServer(action.getEntityId());

 case "START":
 return startDeliveryOnServer(action.getEntityId());

 case "COMPLETE":
 return completeDeliveryOnServer(action.getEntityId());

 case "MARK_DELIVERED":
 return markDeliveryAsDeliveredOnServer(action.getEntityId());

 case "MARK_FAILED":
 return markDeliveryAsFailedOnServer(action.getEntityId());

 default:
 Log.w(TAG, "Unknown delivery action: " + action.getActionType());
 return false;
 }
 } catch (Exception e) {
 Log.e(TAG, "Error processing delivery action", e);
 return false;
 }
 }

 /**
 * Handle action processing failure with retry logic
 */
 private void handleActionFailure(OfflineActionEntity action, String errorMessage) {
 try {
 int currentRetryCount = action.getRetryCount();

 if (currentRetryCount < MAX_RETRY_ATTEMPTS) {
 // Increment retry count and schedule for retry
 offlineActionDao.incrementRetryCount(action.getId());

 // Set next retry time with exponential backoff
 long nextRetryTime = System.currentTimeMillis() + (RETRY_DELAY_MS * (1L << currentRetryCount));
 offlineActionDao.setNextRetryTime(action.getId(), nextRetryTime);

 Log.d(TAG, "Scheduled action for retry " + (currentRetryCount + 1) + "/" + MAX_RETRY_ATTEMPTS);
 } else {
 // Max retries exceeded, mark as failed
 offlineActionDao.markActionFailed(action.getId(), errorMessage);
 Log.w(TAG, "Action failed permanently after " + MAX_RETRY_ATTEMPTS + " retries: " + errorMessage);
 }
 } catch (Exception e) {
 Log.e(TAG, "Error handling action failure", e);
 }
 }

 /**
 * Create batches from a list of actions
 */
 private List<List<OfflineActionEntity>> createBatches(List<OfflineActionEntity> actions, int batchSize) {
 List<List<OfflineActionEntity>> batches = new ArrayList<>();

 for (int i = 0; i < actions.size(); i += batchSize) {
 int endIndex = Math.min(i + batchSize, actions.size());
 batches.add(actions.subList(i, endIndex));
 }

 return batches;
 }

 /**
 * Get count of pending actions by type
 */
 public CompletableFuture<Integer> getPendingActionsCount() {
 return CompletableFuture.supplyAsync(() -> {
 try {
 return offlineActionDao.getPendingActionsCount();
 } catch (Exception e) {
 Log.e(TAG, "Error getting pending actions count", e);
 return 0;
 }
 }, executorService);
 }

 /**
 * Get count of failed actions
 */
 public CompletableFuture<Integer> getFailedActionsCount() {
 return CompletableFuture.supplyAsync(() -> {
 try {
 return offlineActionDao.getFailedActionsCount();
 } catch (Exception e) {
 Log.e(TAG, "Error getting failed actions count", e);
 return 0;
 }
 }, executorService);
 }

 /**
 * Cleanup old completed actions
 */
 public CompletableFuture<Void> cleanupOldActions() {
 return CompletableFuture.runAsync(() -> {
 try {
 long cutoffTime = System.currentTimeMillis() - (7 * 24 * 60 * 60 * 1000L); // 7 days
 int deleted = offlineActionDao.deleteOldCompletedActions(cutoffTime);
 Log.d(TAG, "Cleaned up " + deleted + " old completed actions");
 } catch (Exception e) {
 Log.e(TAG, "Error cleaning up old actions", e);
 }
 }, executorService);
 }

