+ private DeliveryEntity convertDeliveryDtoToEntity(com.clone.EasyDelivery.api.models.dto.DeliveryDto dto) {
+ if (dto == null) return null;
+
+ DeliveryEntity entity = new DeliveryEntity();
+
+ // Basic fields
+ entity.setDeliveryId(dto.getDeliveryId());
+ entity.setOrderNumber(dto.getOrderNumber());
+ entity.setAddress(dto.getAddress());
+ entity.setQuantityExpected(dto.getQuantityExpected());
+ entity.setStatus(dto.getStatus());
+
+ // Customer data (from nested CustomerDto)
+ if (dto.getCustomer() != null) {
+ entity.setCustomerName(dto.getCustomer().getName());
+ entity.setCustomerContact(dto.getCustomer().getContact());
+ entity.setCustomerNumber(dto.getCustomer().getNumber());
+ entity.setCustomerEmail(dto.getCustomer().getEmail());
+ }
+
+ // GPS Location (from nested GpsLocationDto)
