+ for (TripEntity trip : driverTrips) {
+ trip.setSyncStatus("pending");
+ tripDao.updateTrip(trip);
+ }
+ Log.d(TAG, "Force sync queued for " + driverTrips.size() + " trips");
+ } catch (Exception e) {
+ Log.e(TAG, "Error force syncing trips", e);
+ }
