import androidx.lifecycle.LiveData;
import androidx.room.Dao;
import androidx.room.Delete;
import androidx.room.Insert;
import androidx.room.OnConflictStrategy;
import androidx.room.Query;
import androidx.room.Update;

import com.clone.EasyDelivery.data.entities.DeliveryEntity;

import java.util.List;

/**
 * DAO interface for DeliveryEntity operations
 */
@Dao
public interface DeliveryDao {

 // =================== INSERT OPERATIONS ===================

 @Insert(onConflict = OnConflictStrategy.REPLACE)
 void insertDelivery(DeliveryEntity delivery);

 @Insert(onConflict = OnConflictStrategy.REPLACE)
 void insertDeliveries(List<DeliveryEntity> deliveries);

 // =================== UPDATE OPERATIONS ===================

 @Update
 void updateDelivery(DeliveryEntity delivery);

 @Query("UPDATE deliveries SET status = :status, sync_status = 'pending' WHERE delivery_id = :deliveryId")
 void updateDeliveryStatus(String deliveryId, String status);

 @Query("UPDATE deliveries SET quantity_delivered = :quantityDelivered, recipient_name = :recipientName, " +
 "comment = :comment, captured_latitude = :capturedLat, captured_longitude = :capturedLon, " +
 "delivery_time = :deliveryTime, status = 'delivered', sync_status = 'pending' WHERE delivery_id = :deliveryId")
 void completeDelivery(String deliveryId, int quantityDelivered, String recipientName, String comment,
 Double capturedLat, Double capturedLon, long deliveryTime);

 @Query("UPDATE deliveries SET signature_path = :signaturePath WHERE delivery_id = :deliveryId")
 void updateSignaturePath(String deliveryId, String signaturePath);

 @Query("UPDATE deliveries SET photo_path = :photoPath WHERE delivery_id = :deliveryId")
 void updatePhotoPath(String deliveryId, String photoPath);

 @Query("UPDATE deliveries SET signature_url = :signatureUrl, sync_status = 'pending' WHERE delivery_id = :deliveryId")
 void updateSignatureUrl(String deliveryId, String signatureUrl);

 @Query("UPDATE deliveries SET photo_url = :photoUrl, sync_status = 'pending' WHERE delivery_id = :deliveryId")
 void updatePhotoUrl(String deliveryId, String photoUrl);

 @Query("UPDATE deliveries SET files_uploaded = :filesUploaded, sync_status = 'pending' WHERE delivery_id = :deliveryId")
 void updateFilesUploaded(String deliveryId, boolean filesUploaded);

 // =================== QUERY OPERATIONS ===================

 @Query("SELECT * FROM deliveries WHERE delivery_id = :deliveryId")
 DeliveryEntity getDelivery(String deliveryId);

 @Query("SELECT * FROM deliveries WHERE delivery_id = :deliveryId")
 LiveData<DeliveryEntity> getDeliveryLiveData(String deliveryId);

 @Query("SELECT * FROM deliveries WHERE trip_id = :tripId ORDER BY order_number ASC")
 List<DeliveryEntity> getDeliveriesByTrip(String tripId);

 @Query("SELECT * FROM deliveries WHERE trip_id = :tripId ORDER BY order_number ASC")
 LiveData<List<DeliveryEntity>> getDeliveriesByTripLiveData(String tripId);

 @Query("SELECT * FROM deliveries WHERE trip_id = :tripId AND status = :status ORDER BY order_number ASC")
 List<DeliveryEntity> getDeliveriesByTripAndStatus(String tripId, String status);

 @Query("SELECT * FROM deliveries WHERE trip_id = :tripId AND status = :status ORDER BY order_number ASC")
 LiveData<List<DeliveryEntity>> getDeliveriesByTripAndStatusLiveData(String tripId, String status);

 @Query("SELECT * FROM deliveries WHERE status = :status ORDER BY delivery_time DESC")
 List<DeliveryEntity> getDeliveriesByStatus(String status);

 @Query("SELECT * FROM deliveries WHERE status = :status ORDER BY delivery_time DESC")
 LiveData<List<DeliveryEntity>> getDeliveriesByStatusLiveData(String status);

 @Query("SELECT * FROM deliveries ORDER BY delivery_time DESC")
 List<DeliveryEntity> getAllDeliveries();

 @Query("SELECT * FROM deliveries ORDER BY delivery_time DESC")
 LiveData<List<DeliveryEntity>> getAllDeliveriesLiveData();

 // =================== COMPLETION OPERATIONS ===================

 @Query("SELECT * FROM deliveries WHERE status = 'delivered' ORDER BY delivery_time DESC")
 List<DeliveryEntity> getCompletedDeliveries();

 @Query("SELECT * FROM deliveries WHERE status = 'delivered' ORDER BY delivery_time DESC")
 LiveData<List<DeliveryEntity>> getCompletedDeliveriesLiveData();

 @Query("SELECT * FROM deliveries WHERE trip_id = :tripId AND status = 'delivered'")
 List<DeliveryEntity> getCompletedDeliveriesByTrip(String tripId);

 @Query("SELECT * FROM deliveries WHERE trip_id = :tripId AND status = 'delivered'")
 LiveData<List<DeliveryEntity>> getCompletedDeliveriesByTripLiveData(String tripId);

 @Query("SELECT COUNT(*) FROM deliveries WHERE trip_id = :tripId AND status = 'delivered'")
 int getCompletedDeliveryCount(String tripId);

 @Query("SELECT COUNT(*) FROM deliveries WHERE trip_id = :tripId AND status = 'delivered'")
 LiveData<Integer> getCompletedDeliveryCountLiveData(String tripId);

 // =================== SYNC OPERATIONS ===================

 @Query("SELECT * FROM deliveries WHERE sync_status != 'synced'")
 List<DeliveryEntity> getDeliveriesNeedingSync();

 @Query("SELECT * FROM deliveries WHERE sync_status = 'pending'")
 List<DeliveryEntity> getPendingDeliveries();

 @Query("SELECT * FROM deliveries WHERE sync_status = 'pending' AND status = 'delivered'")
 List<DeliveryEntity> getPendingCompletedDeliveries();

 @Query("SELECT COUNT(*) FROM deliveries WHERE sync_status != 'synced'")
 int getPendingSyncCount();

 @Query("SELECT COUNT(*) FROM deliveries WHERE sync_status != 'synced'")
 LiveData<Integer> getPendingSyncCountLiveData();

 @Query("UPDATE deliveries SET sync_status = 'synced', synced_at = :syncedAt, server_version = :serverVersion WHERE delivery_id = :deliveryId")
 void markAsSynced(String deliveryId, long syncedAt, String serverVersion);

 @Query("UPDATE deliveries SET sync_status = 'pending' WHERE delivery_id = :deliveryId")
 void markAsPending(String deliveryId);

 @Query("UPDATE deliveries SET sync_status = 'error' WHERE delivery_id = :deliveryId")
 void markAsError(String deliveryId);

 // =================== FILE OPERATIONS ===================

 @Query("SELECT * FROM deliveries WHERE (signature_path IS NOT NULL AND signature_path != '') OR (photo_path IS NOT NULL AND photo_path != '')")
 List<DeliveryEntity> getDeliveriesWithFiles();

 @Query("SELECT * FROM deliveries WHERE files_uploaded = 0 AND ((signature_path IS NOT NULL AND signature_path != '') OR (photo_path IS NOT NULL AND photo_path != ''))")
 List<DeliveryEntity> getDeliveriesNeedingFileUpload();

 @Query("SELECT * FROM deliveries WHERE files_uploaded = 1 AND ((signature_url IS NOT NULL AND signature_url != '') OR (photo_url IS NOT NULL AND photo_url != ''))")
 List<DeliveryEntity> getDeliveriesWithUploadedFiles();

 @Query("SELECT COUNT(*) FROM deliveries WHERE files_uploaded = 0 AND ((signature_path IS NOT NULL AND signature_path != '') OR (photo_path IS NOT NULL AND photo_path != ''))")
 int getPendingFileUploadCount();

 @Query("SELECT COUNT(*) FROM deliveries WHERE files_uploaded = 0 AND ((signature_path IS NOT NULL AND signature_path != '') OR (photo_path IS NOT NULL AND photo_path != ''))")
 LiveData<Integer> getPendingFileUploadCountLiveData();

 // =================== SEARCH OPERATIONS ===================

 @Query("SELECT * FROM deliveries WHERE order_number LIKE '%' || :searchTerm || '%' OR customer_name LIKE '%' || :searchTerm || '%' OR address LIKE '%' || :searchTerm || '%'")
 List<DeliveryEntity> searchDeliveries(String searchTerm);

 @Query("SELECT * FROM deliveries WHERE order_number = :orderNumber")
 DeliveryEntity getDeliveryByOrderNumber(String orderNumber);

 @Query("SELECT * FROM deliveries WHERE order_number = :orderNumber")
 LiveData<DeliveryEntity> getDeliveryByOrderNumberLiveData(String orderNumber);

 // =================== STATISTICS ===================

 @Query("SELECT COUNT(*) FROM deliveries WHERE trip_id = :tripId")
 int getTotalDeliveriesForTrip(String tripId);

 @Query("SELECT AVG(delivery_time - (SELECT created_at FROM trips WHERE trip_id = deliveries.trip_id)) " +
 "FROM deliveries WHERE status = 'delivered' AND delivery_time IS NOT NULL")
 Long getAverageDeliveryTime();

 @Query("SELECT COUNT(*) FROM deliveries WHERE status = 'delivered' AND delivery_time >= :fromTime AND delivery_time <= :toTime")
 int getDeliveriesCompletedInTimeRange(long fromTime, long toTime);

 @Query("SELECT SUM(quantity_delivered) FROM deliveries WHERE status = 'delivered' AND quantity_delivered IS NOT NULL")
 Integer getTotalQuantityDelivered();

 // =================== DELETE OPERATIONS ===================

 @Delete
 void deleteDelivery(DeliveryEntity delivery);

 @Query("DELETE FROM deliveries WHERE delivery_id = :deliveryId")
 void deleteDeliveryById(String deliveryId);

 @Query("DELETE FROM deliveries WHERE trip_id = :tripId")
 void deleteDeliveriesByTrip(String tripId);

 @Query("DELETE FROM deliveries WHERE status = :status")
 void deleteDeliveriesByStatus(String status);

 @Query("DELETE FROM deliveries WHERE delivery_time < :cutoffTime")
 void deleteOldDeliveries(long cutoffTime);

 @Query("DELETE FROM deliveries")
 void deleteAllDeliveries();

 // =================== UTILITY OPERATIONS ===================

 @Query("SELECT EXISTS(SELECT 1 FROM deliveries WHERE delivery_id = :deliveryId)")
 boolean deliveryExists(String deliveryId);

 @Query("SELECT EXISTS(SELECT 1 FROM deliveries WHERE order_number = :orderNumber)")
 boolean orderNumberExists(String orderNumber);

 @Query("SELECT status FROM deliveries WHERE delivery_id = :deliveryId")
 String getDeliveryStatus(String deliveryId);

 @Query("SELECT trip_id FROM deliveries WHERE delivery_id = :deliveryId")
 String getTripIdForDelivery(String deliveryId);

 @Query("SELECT COUNT(*) FROM deliveries")
 int getTotalCount();

 /**
 * Get next delivery in sequence for a trip
 */
 @Query("SELECT * FROM deliveries WHERE trip_id = :tripId AND status = 'pending' ORDER BY order_number ASC LIMIT 1")
 DeliveryEntity getNextDeliveryForTrip(String tripId);

 /**
 * Get delivery progress for trip
 */
 @Query("SELECT COUNT(*) as total, SUM(CASE WHEN status = 'delivered' THEN 1 ELSE 0 END) as completed FROM deliveries WHERE trip_id = :tripId")
 DeliveryProgress getDeliveryProgress(String tripId);

 /**
 * Alias for getDeliveriesNeedingSync() for backward compatibility
 */
 @Query("SELECT * FROM deliveries WHERE sync_status != 'synced'")
 List<DeliveryEntity> getUnsyncedDeliveries();

 // Inner class for delivery progress
 public static class DeliveryProgress {
 public int total;
 public int completed;

 public DeliveryProgress(int total, int completed) {
 this.total = total;
 this.completed = completed;
 }

 public float getProgressPercentage() {
 if (total == 0) return 0f;
 return (float) completed / total * 100f;
 }

 public boolean isCompleted() {
 return completed >= total && total > 0;
 }
 }
}"},{"role":"tool","name":"read_file","tool_call_id":"toolu_0193RKEBYJdTHpqL53pqeBfE","content":"package com.clone.EasyDelivery.data.dao;

import androidx.lifecycle.LiveData;
import androidx.room.ColumnInfo;
import androidx.room.Dao;
import androidx.room.Delete;
import androidx.room.Insert;
import androidx.room.OnConflictStrategy;
import androidx.room.Query;
import androidx.room.Update;

import com.clone.EasyDelivery.data.entities.TripEntity;

import java.util.List;

/**
 * DAO interface for TripEntity operations
 */
@Dao
public interface TripDao {

 // =================== INSERT OPERATIONS ===================

 @Insert(onConflict = OnConflictStrategy.REPLACE)
 void insertTrip(TripEntity trip);

 @Insert(onConflict = OnConflictStrategy.REPLACE)
 void insertTrips(List<TripEntity> trips);

 // =================== UPDATE OPERATIONS ===================

 @Update
 void updateTrip(TripEntity trip);

 @Query("UPDATE trips SET status = :status, sync_status = 'pending' WHERE trip_id = :tripId")
 void updateTripStatus(String tripId, String status);

 @Query("UPDATE trips SET status = 'claimed', session_id = :sessionId, driver_id = :driverId, " +
 "claimed_at = :claimedAt, sync_status = 'pending' WHERE trip_id = :tripId")
 void claimTrip(String tripId, String sessionId, String driverId, long claimedAt);

 @Query("UPDATE trips SET status = 'in_progress', started_at = :startedAt, sync_status = 'pending' WHERE trip_id = :tripId")
 void startTrip(String tripId, long startedAt);

 @Query("UPDATE trips SET status = 'completed', completed_at = :completedAt, sync_status = 'pending' WHERE trip_id = :tripId")
 void completeTrip(String tripId, long completedAt);

 @Query("UPDATE trips SET completed_deliveries = completed_deliveries + 1, sync_status = 'pending' WHERE trip_id = :tripId")
 void incrementCompletedDeliveries(String tripId);

 @Query("UPDATE trips SET total_deliveries = :totalDeliveries WHERE trip_id = :tripId")
 void updateTotalDeliveries(String tripId, int totalDeliveries);

 // =================== QUERY OPERATIONS ===================

 @Query("SELECT * FROM trips WHERE trip_id = :tripId")
 TripEntity getTrip(String tripId);

 @Query("SELECT * FROM trips WHERE trip_id = :tripId")
 LiveData<TripEntity> getTripLiveData(String tripId);

 @Query("SELECT * FROM trips WHERE client_id = :clientId ORDER BY created_at DESC")
 List<TripEntity> getTripsByClient(String clientId);

 @Query("SELECT * FROM trips WHERE client_id = :clientId ORDER BY created_at DESC")
 LiveData<List<TripEntity>> getTripsByClientLiveData(String clientId);

 @Query("SELECT * FROM trips WHERE status = :status ORDER BY created_at DESC")
 List<TripEntity> getTripsByStatus(String status);

 @Query("SELECT * FROM trips WHERE status = :status ORDER BY created_at DESC")
 LiveData<List<TripEntity>> getTripsByStatusLiveData(String status);

 @Query("SELECT * FROM trips WHERE client_id = :clientId AND status = :status ORDER BY created_at DESC")
 List<TripEntity> getTripsByClientAndStatus(String clientId, String status);

 @Query("SELECT * FROM trips WHERE client_id = :clientId AND status = :status ORDER BY created_at DESC")
 LiveData<List<TripEntity>> getTripsByClientAndStatusLiveData(String clientId, String status);

 @Query("SELECT * FROM trips WHERE driver_id = :driverId ORDER BY created_at DESC")
 List<TripEntity> getTripsByDriver(String driverId);

 @Query("SELECT * FROM trips WHERE driver_id = :driverId ORDER BY created_at DESC")
 LiveData<List<TripEntity>> getTripsByDriverLiveData(String driverId);

 @Query("SELECT * FROM trips WHERE session_id = :sessionId ORDER BY created_at DESC")
 List<TripEntity> getTripsBySession(String sessionId);

 @Query("SELECT * FROM trips WHERE session_id = :sessionId ORDER BY created_at DESC")
 LiveData<List<TripEntity>> getTripsBySessionLiveData(String sessionId);

 // =================== ACTIVE TRIP OPERATIONS ===================

 @Query("SELECT * FROM trips WHERE driver_id = :driverId AND status IN ('claimed', 'in_progress') ORDER BY claimed_at ASC")
 List<TripEntity> getActiveTripsForDriver(String driverId);

 @Query("SELECT * FROM trips WHERE driver_id = :driverId AND status IN ('claimed', 'in_progress') ORDER BY claimed_at ASC")
 LiveData<List<TripEntity>> getActiveTripsForDriverLiveData(String driverId);

 @Query("SELECT * FROM trips WHERE session_id = :sessionId AND status IN ('claimed', 'in_progress') ORDER BY claimed_at ASC")
 List<TripEntity> getActiveTripsForSession(String sessionId);

 @Query("SELECT COUNT(*) FROM trips WHERE driver_id = :driverId AND status IN ('claimed', 'in_progress')")
 int getActiveTripsCount(String driverId);

 @Query("SELECT COUNT(*) FROM trips WHERE driver_id = :driverId AND status IN ('claimed', 'in_progress')")
 LiveData<Integer> getActiveTripsCountLiveData(String driverId);

 // =================== SYNC OPERATIONS ===================

 @Query("SELECT * FROM trips WHERE sync_status != 'synced'")
 List<TripEntity> getTripsNeedingSync();

 @Query("SELECT * FROM trips WHERE sync_status != 'synced'")
 LiveData<List<TripEntity>> getTripsNeedingSyncLiveData();

 @Query("SELECT * FROM trips WHERE sync_status = 'pending'")
 List<TripEntity> getPendingTrips();

 @Query("SELECT COUNT(*) FROM trips WHERE sync_status != 'synced'")
 int getPendingSyncCount();

 @Query("SELECT COUNT(*) FROM trips WHERE sync_status != 'synced'")
 LiveData<Integer> getPendingSyncCountLiveData();

 @Query("UPDATE trips SET sync_status = 'synced', synced_at = :syncedAt, server_version = :serverVersion WHERE trip_id = :tripId")
 void markAsSynced(String tripId, long syncedAt, String serverVersion);

 @Query("UPDATE trips SET sync_status = 'pending' WHERE trip_id = :tripId")
 void markAsPending(String tripId);

 @Query("UPDATE trips SET sync_status = 'error' WHERE trip_id = :tripId")
 void markAsError(String tripId);

 // =================== STATISTICS ===================

 @Query("SELECT COUNT(*) FROM trips WHERE client_id = :clientId AND status = 'completed'")
 int getCompletedTripsCount(String clientId);

 @Query("SELECT COUNT(*) FROM trips WHERE driver_id = :driverId AND status = 'completed'")
 int getCompletedTripsCountByDriver(String driverId);

 @Query("SELECT AVG(completed_at - started_at) FROM trips WHERE status = 'completed' AND started_at IS NOT NULL AND completed_at IS NOT NULL")
 Long getAverageTripDuration();

 @Query("SELECT SUM(completed_deliveries) FROM trips WHERE driver_id = :driverId AND status = 'completed'")
 int getTotalDeliveriesCompleted(String driverId);

 // =================== DELETE OPERATIONS ===================

 @Delete
 void deleteTrip(TripEntity trip);

 @Query("DELETE FROM trips WHERE trip_id = :tripId")
 void deleteTripById(String tripId);

 @Query("DELETE FROM trips WHERE client_id = :clientId")
 void deleteTripsByClient(String clientId);

 @Query("DELETE FROM trips WHERE status = :status")
 void deleteTripsByStatus(String status);

 @Query("DELETE FROM trips")
 void deleteAllTrips();

 // =================== UTILITY OPERATIONS ===================

 @Query("SELECT EXISTS(SELECT 1 FROM trips WHERE trip_id = :tripId)")
 boolean tripExists(String tripId);

 @Query("SELECT status FROM trips WHERE trip_id = :tripId")
 String getTripStatus(String tripId);

 @Query("SELECT driver_id FROM trips WHERE trip_id = :tripId")
 String getTripDriverId(String tripId);

 @Query("SELECT session_id FROM trips WHERE trip_id = :tripId")
 String getTripSessionId(String tripId);

 @Query("SELECT completed_deliveries, total_deliveries FROM trips WHERE trip_id = :tripId")
 TripProgressInfo getTripProgress(String tripId);

 @Query("SELECT COUNT(*) FROM trips")
 int getTotalCount();

 /**
 * Get trips that are stale (claimed/started but not updated recently)
 */
 @Query("SELECT * FROM trips WHERE status IN ('claimed', 'in_progress') AND " +
 "(claimed_at < :staleTime OR started_at < :staleTime)")
 List<TripEntity> getStaleTrips(long staleTime);

 /**
 * Release trips that have been claimed but not started within timeout
 */
 @Query("UPDATE trips SET status = 'available', session_id = NULL, driver_id = NULL, " +
 "claimed_at = NULL, sync_status = 'pending' WHERE status = 'claimed' AND claimed_at < :timeoutTime")
 void releaseExpiredClaims(long timeoutTime);

 /**
 * Alias for getTripsNeedingSync() for backward compatibility
 */
 @Query("SELECT * FROM trips WHERE sync_status != 'synced'")
 List<TripEntity> getUnsyncedTrips();

 // Inner class for trip progress info
 public static class TripProgressInfo {
 @ColumnInfo(name = "completed_deliveries")
 public int completedDeliveries;

 @ColumnInfo(name = "total_deliveries")
 public int totalDeliveries;

 public TripProgressInfo(int completedDeliveries, int totalDeliveries) {
 this.completedDeliveries = completedDeliveries;
 this.totalDeliveries = totalDeliveries;
 }

 public float getProgressPercentage() {
 if (totalDeliveries == 0) return 0f;
 return (float) completedDeliveries / totalDeliveries * 100f;
 }

 public boolean isCompleted() {
 return completedDeliveries >= totalDeliveries && totalDeliveries > 0;
 }
 }
}"},{"role":"assistant","content":[{"type":"text","text":"Now I can see the real issues. You're absolutely right to be frustrated. Let me analyze what's actually broken:

## **Real Problems I Found:**

### **1. API Services Have Major Design Issues:**

**AuthService Problems:**
- Uses inner classes (`DeviceStatusResponse`, `DriversResponse`) **inside an interface** - this is poor design
- These inner classes extend `BaseApiResponse` but that's not how Retrofit response handling should work
- Mixing response DTOs with service definitions

**DeliveryService Problems:**
- Same inner class antipattern 
- `DeliveriesResponse.getDeliveries()` returns `List<DeliveryDto>` but actual responses will be different structure
- Endpoints like `/deliveries/{deliveryId}` without trip context likely won't work with real API

**TripService Problems:** 
- Uses `ClaimTripRequest` for three different operations (`claimTrip`, `startTrip`, `completeTrip`) - that's wrong
- Missing proper request/response DTOs

### **2. Room Implementation Issues:**

**Missing Critical DAO Methods:**
Looking at repositories calling DAOs, several methods don't exist:
- `getTripById()` with `forceFresh` parameter
- `getFirstActiveTripForDriverLiveData()`
- Various method signature mismatches

**Database Migration Problems:**
- Migration from version 0 to 1 tries to migrate from legacy tables that may not exist
- No proper error handling if migration fails
- Legacy table structure assumptions may be wrong

### **3. Repository/Service Integration Broken:**

**DeliveryRepository Issues:**
```java
// This will fail - wrong return type conversion
Call<DeliveriesResponse> call = deliveryService.getDeliveriesForTrip(tripId);
Response<List<DeliveryEntity>> response = call.execute(); // WRONG!
```

The service returns `Call<DeliveriesResponse>` but repository expects `Response<List<DeliveryEntity>>`.

**TripRepository Issues:**
```java
// convertTripDtoToEntity calls dto.getSessionInfo().getDriverId()
// but SessionInfoDto might not have getDriverId()
```

## **What Actually Needs To Be Fixed:**

1. **Redesign API Services** - Remove inner classes, create proper DTO structure
2. **Fix DAO method signatures** - Add missing methods repositories are calling 
3. **Fix Repository response mapping** - Properly convert DTOs to Entities
4. **Review Room annotations** - Several entities likely have annotation issues
5. **Fix database migration** - Handle legacy migration properly

This is **way more than package import issues** - there are fundamental architectural problems with the API integration and data layer.

Would you like me to start fixing these **real structural problems** instead of just compilation errors?"}]},{"role":"user","content":[{"type":"text","text":"<user_query>
