 Context appContext,
 String workerClassName,
 WorkerParameters workerParameters
 ) {
 if (workerClassName.equals(SyncWorker.class.getName())) {
 return new SyncWorker(
 appContext,
 workerParameters,
 syncManager
 );
 }

 // Return null to delegate to the default factory
 return null;
 }
