 private AuthRepository(Context context) {
 this.context = context.getApplicationContext();
 this.apiClient = RetrofitApiClient.getInstance(context);
 this.authService = apiClient.getAuthService();
 this.database = DeliveryDatabase.getInstance(context);
 this.deviceDao = database.deviceDao();
 this.sessionDao = database.sessionDao();
 this.securePreferences = SecurePreferences.getInstance(context);
 this.syncManager = SyncManager.getInstance(context);
 this.executor = Executors.newFixedThreadPool(2);

 // Get device information
 this.deviceId = DeviceUtils.getDeviceId(context);
 this.deviceType = DeviceUtils.getDeviceType();

 Log.i(TAG, "AuthRepository initialized for device: " + deviceId);
 }

 public static AuthRepository getInstance(Context context) {
 if (INSTANCE == null) {
 synchronized (AuthRepository.class) {
 if (INSTANCE == null) {
 INSTANCE = new AuthRepository(context);
 }
 }
 }
 return INSTANCE;
