 private void setupListeners() {
 // Enrollment key validation
 btnValidateKey.setOnClickListener(v -> {
 String enrollmentKey = etEnrollmentKey.getText().toString().trim();
 if (!enrollmentKey.isEmpty()) {
 authViewModel.validateEnrollmentKey(enrollmentKey);
 } else {
 Toast.makeText(this, "Please enter enrollment key", Toast.LENGTH_SHORT).show();
 }
 });

 // Device registration
 btnRegisterDevice.setOnClickListener(v -> {
 String enrollmentKey = etEnrollmentKey.getText().toString().trim();
 if (!enrollmentKey.isEmpty()) {
 authViewModel.registerDevice(enrollmentKey);
 } else {
 Toast.makeText(this, "Please enter enrollment key", Toast.LENGTH_SHORT).show();
 }
 });

 // Driver authentication
 btnLogin.setOnClickListener(v -> {
 String driverId = etDriverId.getText().toString().trim();
 String pin = etPin.getText().toString().trim();

 if (!driverId.isEmpty() && !pin.isEmpty()) {
 authViewModel.authenticateDriver(driverId, pin);
 } else {
 Toast.makeText(this, "Please enter Driver ID and PIN", Toast.LENGTH_SHORT).show();
 }
 });

 // Session start
 btnStartSession.setOnClickListener(v -> {
 // For demo purposes, use a default vehicle info
 String vehicleInfo = "Mobile Device - " + android.os.Build.MODEL;
 authViewModel.startSession(vehicleInfo);
 });

 // PIN validation on text change
 etPin.addTextChangedListener(new TextWatcher() {
 @Override
 public void beforeTextChanged(CharSequence s, int start, int count, int after) {}

 @Override
 public void onTextChanged(CharSequence s, int start, int before, int count) {
 authViewModel.validatePinInput(s.toString());
 }

 @Override
 public void afterTextChanged(Editable s) {}
 });
 }

 private void setupObservers() {
 // Observe authentication state changes
 authViewModel.getAuthState().observe(this, authState -> {
 updateUIForAuthState(authState);
 });

 // Observe loading state
 authViewModel.getIsLoading().observe(this, isLoading -> {
 progressBar.setVisibility(isLoading ? View.VISIBLE : View.GONE);
 });

 // Observe error messages
 authViewModel.getErrorMessage().observe(this, errorMessage -> {
 if (errorMessage != null && !errorMessage.isEmpty()) {
 tvStatus.setText("Error: " + errorMessage);
 tvStatus.setTextColor(getResources().getColor(android.R.color.holo_red_dark));
 }
 });

 // Observe enrollment key validation
 authViewModel.getEnrollmentKeyValidationState().observe(this, state -> {
 if (state != null) {
 if (state.isSuccess()) {
 tvStatus.setText("Enrollment key valid! You can register your device.");
 tvStatus.setTextColor(getResources().getColor(android.R.color.holo_green_dark));
 btnRegisterDevice.setEnabled(true);
 } else if (state.isError()) {
 tvStatus.setText("Invalid enrollment key: " + state.getErrorMessage());
 tvStatus.setTextColor(getResources().getColor(android.R.color.holo_red_dark));
 btnRegisterDevice.setEnabled(false);
 }
 }
 });

 // Observe device registration
 authViewModel.getDeviceRegistrationState().observe(this, state -> {
 if (state != null && state.isSuccess()) {
 tvStatus.setText("Device registered successfully! You can now log in.");
 tvStatus.setTextColor(getResources().getColor(android.R.color.holo_green_dark));
 }
 });

 // Observe driver authentication
 authViewModel.getDriverAuthenticationState().observe(this, state -> {
 if (state != null && state.isSuccess()) {
 tvStatus.setText("Authentication successful! You can start a session.");
 tvStatus.setTextColor(getResources().getColor(android.R.color.holo_green_dark));
 }
 });

 // Observe session state
 authViewModel.getSessionState().observe(this, state -> {
 if (state != null && state.isSuccess()) {
 tvStatus.setText("Session started successfully!");
 tvStatus.setTextColor(getResources().getColor(android.R.color.holo_green_dark));

 // Navigate to TripDash
 navigateToTripDash();
 }
 });

 // Observe PIN validation messages
 authViewModel.getPinValidationMessage().observe(this, message -> {
 tvPinValidation.setText(message);
 if (message.contains("Strong") || message.contains("Good")) {
 tvPinValidation.setTextColor(getResources().getColor(android.R.color.holo_green_dark));
 } else if (message.contains("Basic")) {
 tvPinValidation.setTextColor(getResources().getColor(android.R.color.holo_orange_dark));
 } else if (!message.isEmpty()) {
 tvPinValidation.setTextColor(getResources().getColor(android.R.color.holo_red_dark));
 }
 });

 // Observe sync status
 authViewModel.getSyncStatus().observe(this, syncStatus -> {
 if (syncStatus != null) {
 Log.d(TAG, "Sync status: " + syncStatus);
 // Could show sync indicator in UI
 }
 });
 }

 private void updateUIForAuthState(AuthState authState) {
 if (authState == null) return;

 switch (authState) {
 case NOT_AUTHENTICATED:
 showEnrollmentSection();
 break;

 case DEVICE_REGISTERED:
 showLoginSection();
 break;

 case AUTHENTICATED:
 showSessionSection();
 break;

 case SESSION_ACTIVE:
 navigateToTripDash();
 break;

 case AUTHENTICATION_FAILED:
 tvStatus.setText("Authentication failed. Please try again.");
 tvStatus.setTextColor(getResources().getColor(android.R.color.holo_red_dark));
 break;
 }
 }

 private void showEnrollmentSection() {
 layoutEnrollment.setVisibility(View.VISIBLE);
 layoutRegistration.setVisibility(View.VISIBLE);
 layoutLogin.setVisibility(View.GONE);
 layoutSession.setVisibility(View.GONE);

 tvStatus.setText("Enter your enrollment key to register this device.");
 tvStatus.setTextColor(getResources().getColor(android.R.color.black));

 btnRegisterDevice.setEnabled(false);
 }

 private void showLoginSection() {
 layoutEnrollment.setVisibility(View.GONE);
 layoutRegistration.setVisibility(View.GONE);
 layoutLogin.setVisibility(View.VISIBLE);
 layoutSession.setVisibility(View.GONE);

 tvStatus.setText("Device registered. Enter your Driver ID and PIN to log in.");
 tvStatus.setTextColor(getResources().getColor(android.R.color.black));
 }

 private void showSessionSection() {
 layoutEnrollment.setVisibility(View.GONE);
 layoutRegistration.setVisibility(View.GONE);
 layoutLogin.setVisibility(View.GONE);
 layoutSession.setVisibility(View.VISIBLE);

 tvStatus.setText("Authenticated successfully. Start your session to begin deliveries.");
 tvStatus.setTextColor(getResources().getColor(android.R.color.holo_green_dark));
 }

 private void navigateToTripDash() {
 Log.i(TAG, "Navigation to TripDash - session active");
 Intent intent = new Intent(this, TripDash.class);
 startActivity(intent);
 finish();
 }

 @Override
 protected void onResume() {
 super.onResume();

 // Check current authentication state on resume
 // This handles cases where the user returns to this activity
 AuthState currentState = authViewModel.getAuthState().getValue();
 if (currentState == AuthState.SESSION_ACTIVE) {
 navigateToTripDash();
 }
 }

 @Override
 public void onBackPressed() {
 // Handle back button based on current state
 AuthState currentState = authViewModel.getAuthState().getValue();

 if (currentState == AuthState.DEVICE_REGISTERED) {
 // Allow going back to enrollment from login
 authViewModel.resetAuthenticationState();
 showEnrollmentSection();
 } else {
 super.onBackPressed();
 }
 }
}
