package com.clone.EasyDelivery.Activity;

import android.Manifest;
import android.content.Intent;
import android.content.SharedPreferences;
import android.content.pm.PackageManager;
import android.os.Build;
import android.os.Bundle;
import android.text.Editable;
import android.text.TextWatcher;
import android.text.SpannableStringBuilder;
import android.text.style.RelativeSizeSpan;
import android.util.Log;
import android.util.Patterns;
import android.view.KeyEvent;
import android.view.View;
import android.view.animation.AlphaAnimation;
import android.view.animation.Animation;
import android.view.animation.AnimationSet;
import android.view.animation.AnimationUtils;
import android.view.animation.DecelerateInterpolator;
import android.view.inputmethod.EditorInfo;
import android.widget.Toast;

import androidx.annotation.NonNull;
import androidx.appcompat.app.AppCompatActivity;
import androidx.core.app.ActivityCompat;
import androidx.core.content.ContextCompat;
import androidx.lifecycle.ViewModelProvider;

import com.clone.EasyDelivery.R;
import com.clone.EasyDelivery.databinding.ActivitySplashBinding;
import com.clone.EasyDelivery.viewmodel.AuthViewModel;
import com.clone.EasyDelivery.viewmodel.models.AuthState;
import com.clone.EasyDelivery.viewmodel.models.UiState;

import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;


/**
 * Modern SplashLogin Activity using AuthViewModel and ViewBinding
 * Handles device enrollment, registration, and driver authentication
 */
public class SplashLogin extends AppCompatActivity {

 private static final String TAG = "SplashLogin";
 private static final int REQUEST_ID_MULTIPLE_PERMISSIONS = 10000;

 // ViewBinding
 private ActivitySplashBinding binding;

 // ViewModels
 private AuthViewModel authViewModel;

 // State
 private boolean animationCompleted = false;
 private AuthenticationStep currentStep = AuthenticationStep.ENROLLMENT;


 /**
 * Authentication steps for better UX flow
 */
 private enum AuthenticationStep {
 ENROLLMENT, // Validate enrollment key
 REGISTRATION, // Register device 
 AUTHENTICATION, // Authenticate driver
 SESSION // Start session
 }

 @Override
 protected void onCreate(Bundle savedInstanceState) {
 super.onCreate(savedInstanceState);

 // Initialize ViewBinding
 binding = ActivitySplashBinding.inflate(getLayoutInflater());
 setContentView(binding.getRoot());

 // Initialize ViewModel
 authViewModel = new ViewModelProvider(this).get(AuthViewModel.class);

 // Check permissions first
 if (!checkAndRequestPermissions()) {
 initializeUI();
 }

 // Setup observers
 setupObservers();

 // Restore saved data
 restoreSavedData();

 // Check if already authenticated
 checkAuthenticationState();
 }

 /**
 * Initialize UI components and event listeners
 */
 private void initializeUI() {
 animateLogo();

 // Setup click listeners
 binding.btnLogin.setOnClickListener(v -> handleProceedClick());

 // Setup text change listeners for real-time validation
 binding.etCom.addTextChangedListener(new SimpleTextWatcher() {
 @Override
 public void afterTextChanged(Editable s) {
 validateEnrollmentKey(s.toString());
 }
 });

 binding.etDriver.addTextChangedListener(new SimpleTextWatcher() {
 @Override
 public void afterTextChanged(Editable s) {
 authViewModel.validatePinInput(s.toString());
 }
 });

 // Email validation on editor action
 binding.etEmail.setOnEditorActionListener((v, actionId, event) -> {
 if (actionId == EditorInfo.IME_ACTION_NEXT) {
 if (!isValidEmail(binding.etEmail.getText().toString())) {
 showValidationError("Invalid Email. Please Re-enter");
 return true;
 }
 }
 return false;
 });
 }

 /**
 * Setup LiveData observers for ViewModel state changes
 */
 private void setupObservers() {
 // Observe authentication state changes
 authViewModel.getAuthState().observe(this, this::handleAuthStateChange);

 // Observe loading state
 authViewModel.getIsLoading().observe(this, this::handleLoadingStateChange);

 // Observe enrollment key validation
 authViewModel.getEnrollmentKeyValidationState().observe(this, this::handleEnrollmentValidation);

 // Observe device registration
 authViewModel.getDeviceRegistrationState().observe(this, this::handleDeviceRegistration);

 // Observe driver authentication
 authViewModel.getDriverAuthenticationState().observe(this, this::handleDriverAuthentication);

 // Observe session state
 authViewModel.getSessionState().observe(this, this::handleSessionState);

 // Observe PIN validation messages
 authViewModel.getPinValidationMessage().observe(this, message -> {
 if (message != null && !message.isEmpty()) {
 binding.etDriver.setHint(message);
 }
 });

 // Observe error messages
 authViewModel.getErrorMessage().observe(this, errorMessage -> {
 if (errorMessage != null && !errorMessage.isEmpty()) {
 showError(errorMessage);
 }
 });
 }

 /**
 * Restore previously saved data
 */
 private void restoreSavedData() {
 String savedCompany = getSavedData("COMPANY", "company");
 String savedEmail = getSavedData("EMAIL", "email");
 String savedDriver = getSavedData("DRIVER", "driver");
 String savedVehicle = getSavedData("VEHICLE", "vehicle");

 if (!savedCompany.isEmpty()) binding.etCom.setText(savedCompany);
 if (!savedEmail.isEmpty()) binding.etEmail.setText(savedEmail);
 if (!savedDriver.isEmpty()) binding.etDriver.setText(savedDriver);
 if (!savedVehicle.isEmpty()) binding.etVehicle.setText(savedVehicle);
 }

 /**
 * Check current authentication state and navigate if needed
 */
 private void checkAuthenticationState() {
 // Check if we have an active session (using synchronous method that doesn't access DB)
 if (authViewModel.getCurrentSessionId() != null) {
 Log.i(TAG, "Active session found, navigating to TripDash");
 navigateToTripDash();
 return;
 }

 // Instead of calling canProceedToAuthentication() directly (which blocks main thread),
 // we'll observe the AuthState LiveData and handle state changes in handleAuthStateChange()
 // The async initialization in AuthViewModel will determine the correct state
 Log.i(TAG, "Waiting for authentication state to be determined asynchronously");
 }

 /**
 * Handle the proceed button click based on current step
 */
 private void handleProceedClick() {
 if (!validateCurrentStep()) {
 return;
 }

 saveCurrentData();

 switch (currentStep) {
 case ENROLLMENT:
 authViewModel.validateEnrollmentKey(binding.etCom.getText().toString().trim());
 break;
 case REGISTRATION:
 authViewModel.registerDevice(binding.etCom.getText().toString().trim());
 break;
 case AUTHENTICATION:
 String driverId = binding.etDriver.getText().toString().trim();
 String pin = binding.etVehicle.getText().toString().trim();
 authViewModel.authenticateDriver(driverId, pin);
 break;
 case SESSION:
 String vehicleInfo = binding.etEmail.getText().toString().trim();
 authViewModel.startSession(vehicleInfo);
 break;
 }
 }

 /**
 * Handle authentication state changes
 */
 private void handleAuthStateChange(AuthState authState) {
 Log.i(TAG, "Auth state changed to: " + authState);

 switch (authState) {
 case NOT_AUTHENTICATED:
 currentStep = AuthenticationStep.ENROLLMENT;
 break;
 case DEVICE_REGISTERED:
 currentStep = AuthenticationStep.AUTHENTICATION;
 break;
 case AUTHENTICATED:
 currentStep = AuthenticationStep.SESSION;
 break;
 case SESSION_ACTIVE:
 navigateToTripDash();
 return;
 }

 updateUIForCurrentStep();
 }

 /**
 * Update UI based on current authentication step
 */
 private void updateUIForCurrentStep() {
 switch (currentStep) {
 case ENROLLMENT:
 binding.btnLogin.setText("Validate Enrollment Key");
 binding.etCom.setHint("Enrollment Key");
 binding.etDriver.setVisibility(View.GONE);
 binding.etVehicle.setVisibility(View.GONE);
 binding.etEmail.setVisibility(View.GONE);
 break;
 case REGISTRATION:
 binding.btnLogin.setText("Register Device");
 break;
 case AUTHENTICATION:
 binding.btnLogin.setText("Authenticate");
 binding.etCom.setHint("Company/Client ID");
 binding.etDriver.setVisibility(View.VISIBLE);
 binding.etDriver.setHint("Driver ID");
 binding.etVehicle.setVisibility(View.VISIBLE);
 binding.etVehicle.setHint("PIN");
 binding.etEmail.setVisibility(View.VISIBLE);
 binding.etEmail.setHint("Email");
 break;
 case SESSION:
 binding.btnLogin.setText("Start Session");
 binding.etEmail.setHint("Vehicle Information");
 break;
 }
 }


 // =================== OBSERVER HANDLERS ===================

 private void handleLoadingStateChange(Boolean isLoading) {
 if (isLoading != null) {
 binding.progressBar.setVisibility(isLoading ? View.VISIBLE : View.GONE);
 binding.btnLogin.setVisibility(isLoading ? View.GONE : View.VISIBLE);

 // Disable input fields during loading
 binding.etCom.setEnabled(!isLoading);
 binding.etEmail.setEnabled(!isLoading);
 binding.etDriver.setEnabled(!isLoading);
 binding.etVehicle.setEnabled(!isLoading);
 }
 }

 private void handleEnrollmentValidation(UiState<String> state) {
 if (state == null) return;

 if (state.isSuccess()) {
 Log.d(TAG, "Enrollment key valid, proceeding to registration");
 currentStep = AuthenticationStep.REGISTRATION;
 updateUIForCurrentStep();

 // Auto-proceed to registration
 authViewModel.registerDevice(binding.etCom.getText().toString().trim());
 } else if (state.isError()) {
 showError("Invalid enrollment key: " + state.getErrorMessage());
 binding.etCom.requestFocus();
 }
 }

 private void handleDeviceRegistration(UiState<String> state) {
 if (state == null) return;

 if (state.isSuccess()) {
 Log.d(TAG, "Device registered successfully");
 showSuccess("Device registered successfully!");
 currentStep = AuthenticationStep.AUTHENTICATION;
 updateUIForCurrentStep();
 } else if (state.isError()) {
 showError("Registration failed: " + state.getErrorMessage());
 }
 }

 private void handleDriverAuthentication(UiState<String> state) {
 if (state == null) return;

 if (state.isSuccess()) {
 Log.d(TAG, "Driver authenticated successfully");
 showSuccess("Authentication successful!");
 currentStep = AuthenticationStep.SESSION;
 updateUIForCurrentStep();
 } else if (state.isError()) {
 showError("Authentication failed: " + state.getErrorMessage());
 binding.etDriver.requestFocus();
 }
 }

 private void handleSessionState(UiState<?> state) {
 if (state == null) return;

 if (state.isSuccess()) {
 Log.d(TAG, "Session started successfully");
 showSuccess("Session started!");
 navigateToTripDash();
 } else if (state.isError()) {
 showError("Session start failed: " + state.getErrorMessage());
 }
 }

 // =================== VALIDATION ===================

 private boolean validateCurrentStep() {
 switch (currentStep) {
 case ENROLLMENT:
 return validateEnrollmentKey(binding.etCom.getText().toString().trim());
 case AUTHENTICATION:
 return validateDriverAuth();
 case SESSION:
 return validateSessionInfo();
 default:
 return true;
 }
 }

 private boolean validateEnrollmentKey(String enrollmentKey) {
 if (enrollmentKey.isEmpty()) {
 showValidationError("Enter enrollment key");
 binding.etCom.requestFocus();
 return false;
 }
 return true;
 }

 private boolean validateDriverAuth() {
 String driverId = binding.etDriver.getText().toString().trim();
 String pin = binding.etVehicle.getText().toString().trim();
 String email = binding.etEmail.getText().toString().trim();

 if (driverId.isEmpty()) {
 showValidationError("Enter driver ID");
 binding.etDriver.requestFocus();
 return false;
 }

 if (pin.isEmpty()) {
 showValidationError("Enter PIN");
 binding.etVehicle.requestFocus();
 return false;
 }

 if (!email.isEmpty() && !isValidEmail(email)) {
 showValidationError("Invalid email format");
 binding.etEmail.requestFocus();
 return false;
 }

 return true;
 }

 private boolean validateSessionInfo() {
 String vehicleInfo = binding.etEmail.getText().toString().trim();

 if (vehicleInfo.isEmpty()) {
 showValidationError("Enter vehicle information");
 binding.etEmail.requestFocus();
 return false;
 }

 return true;
 }


 // =================== UI HELPERS ===================

 private void showError(String message) {
 Log.w(TAG, "Error: " + message);
 Toast.makeText(this, message, Toast.LENGTH_LONG).show();
 }

 private void showSuccess(String message) {
 Log.i(TAG, "Success: " + message);
 Toast.makeText(this, message, Toast.LENGTH_SHORT).show();
 }

 private void showValidationError(String message) {
 SpannableStringBuilder styledText = new SpannableStringBuilder(message);
 styledText.setSpan(new RelativeSizeSpan(1.35f), 0, message.length(), 0);
 Toast.makeText(this, styledText, Toast.LENGTH_SHORT).show();
 }

 private boolean isValidEmail(String email) {
 return Patterns.EMAIL_ADDRESS.matcher(email).matches();
 }

 private void navigateToTripDash() {
 Log.i(TAG, "Navigating to TripDash");
 Intent intent = new Intent(this, TripDash.class);
 startActivity(intent);
 finish();
 }

 private void saveCurrentData() {
 saveData("COMPANY", "company", binding.etCom.getText().toString());
 saveData("EMAIL", "email", binding.etEmail.getText().toString());
 saveData("DRIVER", "driver", binding.etDriver.getText().toString());
 saveData("VEHICLE", "vehicle", binding.etVehicle.getText().toString());
 }

 private String getSavedData(String prefName, String key) {
 SharedPreferences prefs = getSharedPreferences(prefName, MODE_PRIVATE);
 return prefs.getString(key, "");
 }

 private void saveData(String prefName, String key, String value) {
 SharedPreferences.Editor editor = getSharedPreferences(prefName, MODE_PRIVATE).edit();
 editor.putString(key, value);
 editor.apply();
 }

 public void animateLogo() {
 binding.ivSplashLogo.setVisibility(View.VISIBLE);
 Animation fadeIn = new AlphaAnimation(0, 1);
 fadeIn.setInterpolator(new DecelerateInterpolator());
 fadeIn.setDuration(1000);
 fadeIn.setStartOffset(500);

 Animation slide = AnimationUtils.loadAnimation(getApplicationContext(), R.anim.slide_up);
 slide.setStartOffset(1950);
 slide.setDuration(250);
 slide.setInterpolator(getApplicationContext(), android.R.anim.accelerate_decelerate_interpolator);
 slide.setFillAfter(true);

 AnimationSet set = new AnimationSet(false);
 set.addAnimation(fadeIn);
 set.addAnimation(slide);
 set.setFillAfter(true);

 binding.ivSplashLogo.startAnimation(set);

 binding.rlMain.setVisibility(View.VISIBLE);
 binding.btnLogin.setVisibility(View.VISIBLE);

 Animation fadeInLayout = new AlphaAnimation(0, 1);
 fadeInLayout.setInterpolator(new DecelerateInterpolator());
 fadeInLayout.setDuration(600);
 fadeInLayout.setStartOffset(2225);

 binding.rlMain.setAnimation(fadeInLayout);
 binding.btnLogin.setAnimation(fadeInLayout);

 animationCompleted = true;
 updateUIForCurrentStep();
 }

 /**
 * Simple TextWatcher implementation for real-time validation
 */
 private static abstract class SimpleTextWatcher implements TextWatcher {
 @Override
 public void beforeTextChanged(CharSequence s, int start, int count, int after) {}

 @Override
 public void onTextChanged(CharSequence s, int start, int before, int count) {}
 }

 // =================== PERMISSIONS ===================

 private List<String> requiredPermissionsList() {

 int permissionFineLocation = ContextCompat.checkSelfPermission(this, Manifest.permission.ACCESS_FINE_LOCATION);
 int permissionCoarseLocation = ContextCompat.checkSelfPermission(this, Manifest.permission.ACCESS_COARSE_LOCATION);
 int permissionCamera = ContextCompat.checkSelfPermission(this, Manifest.permission.CAMERA);

 List<String> listPermissionsNeeded = new ArrayList<>();

 if (!(Build.VERSION.SDK_INT >= 34)) {
 int permissionWrite = ContextCompat.checkSelfPermission(this, Manifest.permission.WRITE_EXTERNAL_STORAGE);
 int permissionRead = ContextCompat.checkSelfPermission(this, Manifest.permission.READ_EXTERNAL_STORAGE);

 if (permissionWrite != PackageManager.PERMISSION_GRANTED) {

 listPermissionsNeeded.add(Manifest.permission.WRITE_EXTERNAL_STORAGE);

 }
 if (permissionRead != PackageManager.PERMISSION_GRANTED) {

 listPermissionsNeeded.add(Manifest.permission.READ_EXTERNAL_STORAGE);

 }
 }
 if (permissionCamera != PackageManager.PERMISSION_GRANTED) {

 listPermissionsNeeded.add(Manifest.permission.CAMERA);

 }
 if (permissionFineLocation != PackageManager.PERMISSION_GRANTED) {

 listPermissionsNeeded.add(Manifest.permission.ACCESS_FINE_LOCATION);

 }
 if (permissionCoarseLocation != PackageManager.PERMISSION_GRANTED) {

 listPermissionsNeeded.add(Manifest.permission.ACCESS_COARSE_LOCATION);

 }

 return listPermissionsNeeded;
 }

 private boolean checkAndRequestPermissions() {

 List<String> listPermissionsNeeded = requiredPermissionsList();

 if (!listPermissionsNeeded.isEmpty()) {

 ActivityCompat.requestPermissions(this, listPermissionsNeeded.toArray(new String[listPermissionsNeeded.size()]), REQUEST_ID_MULTIPLE_PERMISSIONS);

 return true;
 }

 return false;
 }

 @Override
 public void onRequestPermissionsResult(int requestCode, @NonNull String[] permissions, @NonNull int[] grantResults) {
 super.onRequestPermissionsResult(requestCode, permissions, grantResults);

 if (requiredPermissionsList().isEmpty()) {
 initializeUI();
 }
 }

 @Override
 protected void onDestroy() {
 super.onDestroy();
 if (binding != null) {
 binding = null;
 }
 }
}

