 public string DriverId { get; set; } = string.Empty;
 }

 /// <summary>
 /// Delivery sub-collection under trips - matches deliveries.json schema
 /// Collection path: trips/{tripId}/deliveries/{deliveryId}
 /// Document ID: SHINUMBER (e.g., "DEVSH0001")
