@@ -1,1 +1,133 @@
+package com.clone.EasyDelivery.util;

+import android.content.Context;
+import android.util.Log;
+
+import com.google.auth.oauth2.GoogleCredentials;
+import com.google.auth.oauth2.AccessToken;
+
+import java.io.IOException;
+import java.io.InputStream;
+import java.util.Arrays;
+import java.util.Date;
+
+/**
+ * Service for managing Google service account authentication
+ * Handles token acquisition and refresh for API calls
+ */
+public class GoogleAuthService {
+
+ private static final String TAG = "GoogleAuthService";
+ private static final String SERVICE_ACCOUNT_FILE = "service-account-key.json";
+
+ // Scopes for Cloud Run and Firebase Storage
+ private static final String[] SCOPES = {
+ "https://www.googleapis.com/auth/cloud-platform"
+ };
+
+ private static GoogleAuthService instance;
+ private final Context context;
+ private GoogleCredentials credentials;
+ private AccessToken currentToken;
+ private long tokenExpiryTime = 0;
+
+ private GoogleAuthService(Context context) {
+ this.context = context.getApplicationContext();
+ initializeCredentials();
+ }
+
+ public static synchronized GoogleAuthService getInstance(Context context) {
+ if (instance == null) {
+ instance = new GoogleAuthService(context);
+ }
+ return instance;
+ }
+
+ /**
+ * Initialize Google credentials from service account file
+ */
+ private void initializeCredentials() {
+ try {
+ InputStream serviceAccountStream = context.getAssets().open(SERVICE_ACCOUNT_FILE);
+ credentials = GoogleCredentials.fromStream(serviceAccountStream)
+ .createScoped(Arrays.asList(SCOPES));
+
+ Log.i(TAG, "Google service account credentials initialized successfully");
+
+ } catch (IOException e) {
+ Log.e(TAG, "Failed to initialize Google credentials", e);
+ credentials = null;
+ }
+ }
+
+ /**
+ * Get valid access token (refresh if needed)
+ */
+ public String getAccessToken() {
+ if (credentials == null) {
+ Log.e(TAG, "Credentials not initialized");
+ return null;
+ }
+
+ try {
+ // Check if token is expired or will expire in next 5 minutes
+ long currentTime = System.currentTimeMillis();
+ if (currentToken == null || tokenExpiryTime <= (currentTime + 300000)) {
+ Log.d(TAG, "Refreshing access token");
+ refreshToken();
+ }
+
+ return currentToken != null ? currentToken.getTokenValue() : null;
+
+ } catch (Exception e) {
+ Log.e(TAG, "Failed to get access token", e);
+ return null;
+ }
+ }
+
+ /**
+ * Refresh the access token
+ */
+ private void refreshToken() throws IOException {
+ credentials.refresh();
+ currentToken = credentials.getAccessToken();
+
+ if (currentToken != null) {
+ // Set expiry time (tokens usually valid for 1 hour)
+ Date expirationTime = currentToken.getExpirationTime();
+ tokenExpiryTime = expirationTime != null ?
+ expirationTime.getTime() :
+ System.currentTimeMillis() + 3600000; // 1 hour from now
+
+ Log.d(TAG, "Access token refreshed successfully. Expires at: " +
+ new Date(tokenExpiryTime));
+ }
+ }
+
+ /**
+ * Check if service account is properly configured
+ */
+ public boolean isConfigured() {
+ return credentials != null;
+ }
+
+ /**
+ * Get service account email for logging
+ */
+ public String getServiceAccountEmail() {
+ if (credentials instanceof com.google.auth.oauth2.ServiceAccountCredentials) {
+ return ((com.google.auth.oauth2.ServiceAccountCredentials) credentials)
+ .getClientEmail();
+ }
+ return "unknown";
+ }
+
+ /**
+ * Force token refresh (for testing)
+ */
+ public void forceRefresh() {
+ currentToken = null;
+ tokenExpiryTime = 0;
+ Log.d(TAG, "Forced token refresh");
+ }
+}
