+ if (state == null) return;
+
+ if (state.isSuccess()) {
+ Log.d(TAG, "Available vehicles received successfully");
+ availableVehicles = state.getData();
+ updateVehicleDropdown();
+ } else if (state.isError()) {
+ showError("Failed to retrieve available vehicles: " + state.getErrorMessage());
+ }
