- binding.etVehicle.setVisibility(View.VISIBLE);
- binding.etVehicle.setHint("Select Vehicle");
- binding.etEmail.setVisibility(View.GONE);
- break;
- default:
- // Enrollment cases should redirect to AuthActivity
- Log.w(TAG, "Unexpected step in updateUIForCurrentStep: " + currentStep);
- break;
- }
