e.TYPE_CLASS_NUMBER | android.text.InputType.TYPE_NUMBER_VARIATION_PASSWORD);\n binding.etPin.setText(\"\");\n \n Log.d(TAG, \"UI configured for PIN authentication\");\n }\n\n /**\n * Setup UI specifically for vehicle selection\n */\n private void setupVehicleSelectionUI() {\n // Hide PIN field and show vehicle dropdown\n hideFieldsWithAnimation(binding.llPin);\n showFieldWithAnimation(binding.llVehicle);\n \n // Update button\n updateButton(\"Start session\", false);\n \n // Clear vehicle selection\n binding.etVehicle.setText(\"\");\n \n Log.d(TAG, \"UI configured for vehicle selection\");\n }\n \n /**\n * Hide multiple fields with smooth animation\n */\n private void hideFieldsWithAnimation(View... views) {\n for (View view : views) {\n if (view.getVisibility() == View.VISIBLE) {\n view.animate()\n .alpha(0f)\n .translationY(-20f)\n .setDuration(200)\n .withEndAction(() -> view.setVisibility(View.GONE))\n .start();\n }\n }\n }\n \n /**\n * Show field with smooth animation\n */\n private void showFieldWithAnimation(View view) {\n if (view.getVisibility() != View.VISIBLE) {\n view.setAlpha(0f);\n view.setTranslationY(20f);\n view.setVisibility(View.VISIBLE);\n view.animate()\n .alpha(1f)\n .translationY(0f)\n .setDuration(300)\n .setInterpolator(new android.view.animation.DecelerateInterpolator())\n .start();\n }\n }\n \n /**\n * Update button text and enable/disable state\n */\n private void updateButton(String text, boolean enabled) {\n binding.btnLogin.setText(text);\n binding.btnLogin.setEnabled(enabled);\n binding.btnLogin.setAlpha(enabled ? 1f : 0.6f);\n \n // Improve button styling\n if (enabled) {\n binding.btnLogin.setBackgroundTintList(\n android.content.res.ColorStateList.valueOf(getResources().getColor(R.color.gold))\n );\n } else {\n binding.btnLogin.setBackgroundTintList(\n android.content.res.ColorStateList.valueOf(getResources().getColor(R.color.gold))\n );\n }\n }"}"}}]},{"role":"tool","name":"edit_file","tool_call_id":"toolu_01PyMPNuyArRF3HNLjdKFVf