+ private void handleAvailableDrivers(UiState<List<DriverDto>> state) {
+ if (state == null) return;
+
+ if (state.isSuccess()) {
+ Log.d(TAG, "Available drivers received successfully");
+ availableDrivers = state.getData();
+ updateDriverDropdown();
+ } else if (state.isError()) {
+ showError("Failed to retrieve available drivers: " + state.getErrorMessage());
+ }
+ }
+
+ private void handleAvailableVehicles(UiState<List<VehicleDto>> state) {
+ if (state == null) return;
+
+ if (state.isSuccess()) {
+ Log.d(TAG, "Available vehicles received successfully");
+ availableVehicles = state.getData();
+ updateVehicleDropdown();
+ } else if (state.isError()) {
+ showError("Failed to retrieve available vehicles: " + state.getErrorMessage());
+ }
+ }
+
+ private void updateDriverDropdown() {
+ ArrayAdapter<DriverDto> driverAdapter = new ArrayAdapter<>(this, R.layout.dropdown_item_driver, availableDrivers);
+ driverAdapter.setDropDownViewResource(R.layout.dropdown_item_driver);
+ binding.etDriver.setAdapter(driverAdapter);
+ }
+
+ private void updateVehicleDropdown() {
+ ArrayAdapter<VehicleDto> vehicleAdapter = new ArrayAdapter<>(this, R.layout.dropdown_item_vehicle, availableVehicles);
+ vehicleAdapter.setDropDownViewResource(R.layout.dropdown_item_vehicle);
+ binding.etVehicle.setAdapter(vehicleAdapter);
+ }
+
+ private AuthState getSavedAuthState() {
+ SharedPreferences prefs = getSharedPreferences("AuthState", MODE_PRIVATE);
+ String authState = prefs.getString("authState", "");
+ if (authState.isEmpty()) return null;
+ return AuthState.valueOf(authState);
+ }
+
+ private void saveAuthState(AuthState authState) {
+ SharedPreferences.Editor editor = getSharedPreferences("AuthState", MODE_PRIVATE).edit();
+ editor.putString("authState", authState.name());
+ editor.apply();
+ }
+
+ private void navigateToAuthActivity() {
+ Log.i(TAG, "Preparing to navigate to AuthActivity after splash animation");
+ // Add a small delay to make the transition feel smooth after splash animation
+ binding.ivSplashLogo.postDelayed(() -> {
+ Intent intent = new Intent(this, AuthActivity.class);
+ startActivity(intent);
+ finish();
+ }, 500); // 500ms delay for smooth transition
+ }
 }


