 /**
 * Intelligent auth state checking with caching
 */
 private void checkAuthStateIntelligently() {
 // First check if we have a cached auth state
 AuthState cachedState = getSavedAuthState();

 if (cachedState != null && cachedState == AuthState.DEVICE_REGISTERED) {
 // Device is known to be registered, proceed directly
 Log.i(TAG, "Using cached auth state, proceeding to driver selection");
 pendingAuthState = AuthState.DEVICE_REGISTERED;
 handleAuthState();
 // Schedule background auth verification if needed
 } else {
 // Need to check auth state from API
 Log.i(TAG, "No valid cache, checking authentication from API");
 showAuthCheckingStatus();

 // Check authentication state
 authViewModel.getAuthState().observe(this, authState -> {
 if (authState == null) return;

 // Cache the auth state for future use
 if (authState == AuthState.DEVICE_REGISTERED) {
 saveAuthState(authState);
 }

 hideAuthCheckingStatus();
 pendingAuthState = authState;
 handleAuthState();
 });
 }
 }

