 binding.tvSplashStatus.setAlpha(0f);
 binding.tvSplashStatus.animate()
 .alpha(0.8f)
 .setDuration(300)
 .start();
 }
 }

 /**
 * Hide auth checking status smoothly
 */
 private void hideAuthCheckingStatus() {
 if (binding.tvSplashStatus != null) {
 binding.tvSplashStatus.animate()
