 /**
 * Setup LiveData observers for ViewModel state changes
 */
 private void setupObservers() {
 // Observe loading state
 authViewModel.getIsLoading().observe(this, this::handleLoadingStateChange);

 // Observe available drivers
 authViewModel.getAvailableDriversState().observe(this, this::handleAvailableDrivers);

 // Observe available vehicles 
 authViewModel.getAvailableVehiclesState().observe(this, this::handleAvailableVehicles);

 // Observe driver authentication
 authViewModel.getDriverAuthenticationState().observe(this, this::handleDriverAuthentication);

 // Observe session state
 authViewModel.getSessionState().observe(this, this::handleSessionState);

 // Observe PIN validation messages
 authViewModel.getPinValidationMessage().observe(this, message -> {
 if (message != null && !message.isEmpty()) {
 binding.etPin.setHint(message);
 }
 });

 // Observe error messages
 authViewModel.getErrorMessage().observe(this, errorMessage -> {
 if (errorMessage != null && !errorMessage.isEmpty()) {
 showError(errorMessage);
 }
 });

 // Setup dropdown selection listeners and field validation
 setupFieldListeners();
 }

 /**
 * Setup field listeners for automatic validation and button enabling
 */
 private void setupFieldListeners() {
