 binding.etDriver.setOnItemClickListener((parent, view, position, id) -> {
 selectedDriver = (DriverDto) parent.getItemAtPosition(position);
 updateButton("Continue", true);
 });

 // Vehicle selection listener 
 binding.etVehicle.setOnItemClickListener((parent, view, position, id) -> {
 selectedVehicle = (VehicleDto) parent.getItemAtPosition(position);
 updateButton("Start session", true);
 });

 // PIN input validation
 binding.etPin.addTextChangedListener(new SimpleTextWatcher() {
 @Override
 public void afterTextChanged(Editable s) {
 String pin = s.toString();
 if (pin.length() == 4) {
 updateButton(selectedDriver != null && !selectedDriver.getHasPinSetup() ? "Create PIN" : "Authenticate", true);
 } else {
 updateButton(selectedDriver != null && !selectedDriver.getHasPinSetup() ? "Create PIN" : "Authenticate", false);
 }
 }
 });
 }

 /**
