 */
 private void restoreSavedData() {
 String savedCompany = getSavedData("COMPANY", "company");
 String savedEmail = getSavedData("EMAIL", "email");
 String savedDriver = getSavedData("DRIVER", "driver");
 String savedVehicle = getSavedData("VEHICLE", "vehicle");

 if (!savedCompany.isEmpty()) binding.etCom.setText(savedCompany);
 if (!savedEmail.isEmpty()) binding.etEmail.setText(savedEmail);
 if (!savedDriver.isEmpty()) binding.etDriver.setText(savedDriver);
 if (!savedVehicle.isEmpty()) binding.etVehicle.setText(savedVehicle);
 }

 /**
 * Check current authentication state and navigate if needed
 */
 private void checkAuthenticationState() {
 Log.d(TAG, "Starting authentication state check after splash completion...");

 // Check if device is enrolled/registered
 authViewModel.getAuthState().observe(this, authState -> {
 if (authState == null) return;

 Log.i(TAG, "Auth state determined: " + authState + " (after splash completion)");

 pendingAuthState = authState;
 authStateReceived = true;

 // Hide authentication status immediately once we have the state
 hideAuthenticationStatus();

 // Since animation is already completed, handle immediately
 handleAuthState();
 });
 }

 private void handleAuthState() {
 Log.i(TAG, "Handling auth state: " + pendingAuthState);

 // Hide splash status - we now know where we're going
 if (binding.tvSplashStatus != null) {
 binding.tvSplashStatus.setVisibility(View.INVISIBLE);
 }

 switch (pendingAuthState) {
 case NOT_AUTHENTICATED:
 // Device not enrolled - redirect to AuthActivity
 Log.i(TAG, "Device not enrolled, redirecting to AuthActivity");
 navigateToAuthActivity();
 break;

 case DEVICE_REGISTERED:
 // Device enrolled - start modern driver selection flow
 Log.i(TAG, "Device enrolled, starting driver selection flow");
 currentStep = AuthenticationStep.DRIVER_SELECTION;
 startDriverSelectionFlow();
 break;

 case AUTHENTICATED:
 // Driver authenticated but no session - go directly to vehicle selection
 Log.i(TAG, "Driver already authenticated, showing vehicle selection");
 currentStep = AuthenticationStep.VEHICLE_SELECTION;
 startVehicleSelectionFlow();
 break;

 case SESSION_ACTIVE:
 // Active session exists - go to TripDash
 Log.i(TAG, "Active session found, navigating to TripDash");
 navigateToTripDash();
 break;

 case AUTHENTICATION_FAILED:
 // Authentication failed - restart driver selection and clear selectedDriver
 Log.w(TAG, "Authentication failed, restarting driver selection and clearing selected driver/PIN");
 selectedDriver = null;
 binding.etDriver.setText("");
 binding.etVehicle.setText("");
 currentStep = AuthenticationStep.DRIVER_SELECTION;
 startDriverSelectionFlow();
 showError("Authentication failed. Please try again.");
 break;
 }
 }

 /**
 * Handle the proceed button click based on current step
 */
 private void handleProceedClick() {
 if (!validateCurrentStep()) {
 return;
 }

 saveCurrentData();

 switch (currentStep) {
 case DRIVER_SELECTION:
 // Driver selected - automatically proceed to PIN step
 if (selectedDriver != null) {
 if (!selectedDriver.getHasPinSetup()) {
 currentStep = AuthenticationStep.AUTHENTICATION;
 showPinSetupFlow();
 } else {
 currentStep = AuthenticationStep.AUTHENTICATION;
 showPinAuthenticationFlow();
 }
 } else {
 showError("Please select a driver");
 }
 break;

 case AUTHENTICATION:
 // PIN entered - authenticate or setup
 String pin = binding.etPin.getText().toString().trim();
 if (!selectedDriver.getHasPinSetup()) {
 authViewModel.setupDriverPin(selectedDriver.getDriverId(), pin);
 } else {
 authViewModel.authenticateDriver(selectedDriver.getDriverId(), pin);
 }
 break;

 case VEHICLE_SELECTION:
 // Vehicle selected - start session
 if (selectedVehicle != null) {
 authViewModel.startSession(selectedVehicle.getVehicleId());
 } else {
 showError("Please select a vehicle");
 }
 break;

 default:
 Log.w(TAG, "Unexpected step in handleProceedClick: " + currentStep);
 break;
 }
 }

