 Animation slide = AnimationUtils.loadAnimation(getApplicationContext(), R.anim.slide_up);
 slide.setStartOffset(1950);
 slide.setDuration(250);
 slide.setInterpolator(getApplicationContext(), android.R.anim.accelerate_decelerate_interpolator);
 slide.setFillAfter(true);

 // Add listener to the logo animation set to know when splash visual completes
 slide.setAnimationListener(new Animation.AnimationListener() {
 @Override
 public void onAnimationStart(Animation animation) {
 }

 @Override
 public void onAnimationEnd(Animation animation) {
 // Logo animation completed - now check authentication
 Log.d(TAG, "Splash logo animation completed, starting authentication check");
 animationCompleted = true;

 // Start auth check now that splash is visually complete
 if (!authStateReceived) {
 checkAuthenticationState();
 } else {
 handleAuthState();
 }
 }

 @Override
 public void onAnimationRepeat(Animation animation) {
 }
 });

 AnimationSet set = new AnimationSet(false);
 set.addAnimation(fadeIn);
 set.addAnimation(slide);
 set.setFillAfter(true);

 binding.ivSplashLogo.startAnimation(set);

 // Show status text during splash
 if (binding.tvSplashStatus != null) {
