import android.content.Context;
import android.util.Log;

import com.clone.EasyDelivery.BuildConfig;
import com.clone.EasyDelivery.util.ConnectionManager;
import com.clone.EasyDelivery.Api.services.AuthService;
import com.clone.EasyDelivery.Api.services.DeliveryService;
import com.clone.EasyDelivery.Api.services.TripService;
import com.clone.EasyDelivery.util.GoogleAuthService;

import java.io.IOException;
import java.util.concurrent.TimeUnit;

import okhttp3.Interceptor;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.logging.HttpLoggingInterceptor;
import retrofit2.Retrofit;
import retrofit2.converter.gson.GsonConverterFactory;

/**
 * Modern Retrofit-based API client with proper configuration
 * Replaces the existing basic ApiClient implementation
 */
public class RetrofitApiClient {

 private static final String TAG = "RetrofitApiClient";

 private static RetrofitApiClient instance;
 private final Context context;
 private final Retrofit retrofit;
 private final ConnectionManager connectionManager;

 // Service instances
 private final AuthService authService;
 private final TripService tripService;
 private final DeliveryService deliveryService;

 // Session management
 private String currentSessionId;
 private String currentDeviceId;

 private RetrofitApiClient(Context context) {
 this.context = context.getApplicationContext();
 this.connectionManager = new ConnectionManager(context);
 this.retrofit = createRetrofit();

 // Initialize service interfaces
 this.authService = retrofit.create(AuthService.class);
 this.tripService = retrofit.create(TripService.class);
 this.deliveryService = retrofit.create(DeliveryService.class);

 Log.i(TAG, "RetrofitApiClient initialized with base URL: " + BuildConfig.API_BASE_URL);
 }

 public static synchronized RetrofitApiClient getInstance(Context context) {
 if (instance == null) {
 instance = new RetrofitApiClient(context);
 }
 return instance;
 }

 /**
 * Create configured Retrofit instance with interceptors
 */
 private Retrofit createRetrofit() {
 OkHttpClient.Builder httpClientBuilder = new OkHttpClient.Builder()
 .connectTimeout(BuildConfig.API_TIMEOUT_SECONDS, TimeUnit.SECONDS)
 .readTimeout(BuildConfig.API_TIMEOUT_SECONDS, TimeUnit.SECONDS)
 .writeTimeout(BuildConfig.API_TIMEOUT_SECONDS, TimeUnit.SECONDS);

 // Add logging interceptor for debug builds
 if (BuildConfig.API_DEBUG) {
 HttpLoggingInterceptor loggingInterceptor = new HttpLoggingInterceptor();
 loggingInterceptor.setLevel(HttpLoggingInterceptor.Level.BODY);
 httpClientBuilder.addInterceptor(loggingInterceptor);
 }

 // Add authentication interceptor
 httpClientBuilder.addInterceptor(new AuthenticationInterceptor(context));

 // Add network connection interceptor
 httpClientBuilder.addInterceptor(new NetworkConnectionInterceptor());

 // Add request/response logging interceptor
 httpClientBuilder.addInterceptor(new RequestResponseInterceptor());

 OkHttpClient httpClient = httpClientBuilder.build();

 return new Retrofit.Builder()
 .baseUrl(BuildConfig.API_BASE_URL)
 .client(httpClient)
 .addConverterFactory(GsonConverterFactory.create())
 .build();
 }

 // =================== SERVICE GETTERS ===================

 public AuthService getAuthService() {
 return authService;
 }

 public TripService getTripService() {
 return tripService;
 }

 public DeliveryService getDeliveryService() {
 return deliveryService;
 }

 // =================== SESSION MANAGEMENT ===================

 public void setCurrentSession(String sessionId, String deviceId) {
 this.currentSessionId = sessionId;
 this.currentDeviceId = deviceId;
 Log.i(TAG, "Session set: " + sessionId + " for device: " + deviceId);
 }

 public void clearSession() {
 this.currentSessionId = null;
 this.currentDeviceId = null;
 Log.i(TAG, "Session cleared");
 }

 public String getCurrentSessionId() {
 return currentSessionId;
 }

 public String getCurrentDeviceId() {
 return currentDeviceId;
 }

 public boolean hasActiveSession() {
 return currentSessionId != null && !currentSessionId.trim().isEmpty();
 }

 // =================== INTERCEPTORS ===================

 /**
 * Interceptor to add authentication headers to requests
 */
 private static class AuthenticationInterceptor implements Interceptor {
 private final Context context;
 private GoogleAuthService authService;

 public AuthenticationInterceptor(Context context) {
 this.context = context.getApplicationContext();
 this.authService = new GoogleAuthService(context);
 }

 @Override
 public Response intercept(Chain chain) throws IOException {
 Request originalRequest = chain.request();

 // Skip authentication for health check endpoints
 String url = originalRequest.url().toString();
 if (url.contains("/health") || url.contains("/ping")) {
 return chain.proceed(originalRequest);
 }

 Log.d(TAG, "Getting service account access token...");

 try {
 // Get access token synchronously for the request
 String accessToken = authService.getAccessToken().get();

 if (accessToken != null && !accessToken.isEmpty()) {
 Log.d(TAG, "Adding Bearer token to request");
 Request.Builder requestBuilder = originalRequest.newBuilder();
 requestBuilder.addHeader("Authorization", "Bearer " + accessToken);
 return chain.proceed(requestBuilder.build());
 } else {
 Log.w(TAG, "No access token available for authentication");
 return chain.proceed(originalRequest);
 }
 } catch (Exception e) {
 Log.e(TAG, "Failed to get access token for request", e);
 return chain.proceed(originalRequest);
 }
 }
 }

 /**
 * Interceptor to check network connection before making requests
 */
 private class NetworkConnectionInterceptor implements Interceptor {
 @Override
 public Response intercept(Chain chain) throws IOException {
 if (!connectionManager.hasInternetConnection()) {
 throw new IOException("No internet connection available");
 }

 return chain.proceed(chain.request());
 }
 }

 /**
 * Interceptor for request/response logging and monitoring
 */
 private class RequestResponseInterceptor implements Interceptor {
 @Override
 public Response intercept(Chain chain) throws IOException {
 Request request = chain.request();

 // Log request details
 long startTime = System.currentTimeMillis();
 Log.d(TAG, String.format("Sending request %s on %s", request.url(), chain.connection()));

 Response response = chain.proceed(request);

 // Log response details 
 long endTime = System.currentTimeMillis();
 Log.d(TAG, String.format("Received response for %s in %dms", 
 response.request().url(), (endTime - startTime)));

 // Log errors
 if (!response.isSuccessful()) {
 Log.w(TAG, String.format("Request failed: %s - %d %s", 
 request.url(), response.code(), response.message()));
 }

 return response;
 }
 }

 // =================== UTILITY METHODS ===================

 /**
 * Check if API is reachable
 */
 public boolean isApiReachable() {
 return connectionManager.hasInternetConnection();
 }

 /**
 * Get API base URL
 */
 public String getBaseUrl() {
 return BuildConfig.API_BASE_URL;
 }

 /**
 * Get configured timeout in seconds
 */
 public int getTimeoutSeconds() {
 return BuildConfig.API_TIMEOUT_SECONDS;
 }
}"},{"role":"assistant","content":[{"type":"text","text":"I can see that the Retrofit client is using the default `GsonConverterFactory.create()` without any custom date handling. The issue is that the API is returning an invalid date format that Gson can't parse. Let me create a custom Gson configuration that can handle problematic dates gracefully:"}],"tool_calls":[{"id":"toolu_01GoGz5hJqxP8VK9ATnvuSXv","type":"function","function":{"name":"edit_file","arguments":"{"target_file": "app/src/main/java/com/clone/EasyDelivery/Api/RetrofitApiClient.java", "instructions": "I'm adding a custom Gson configuration with a lenient date deserializer to handle invalid dates from the API", "code_edit": "import com.clone.EasyDelivery.BuildConfig;\nimport com.clone.EasyDelivery.util.ConnectionManager;\nimport com.clone.EasyDelivery.Api.services.AuthService;\nimport com.clone.EasyDelivery.Api.services.DeliveryService;\nimport com.clone.EasyDelivery.Api.services.TripService;\nimport com.clone.EasyDelivery.util.GoogleAuthService;\nimport com.google.gson.Gson;\nimport com.google.gson.GsonBuilder;\nimport com.google.gson.JsonDeserializationContext;\nimport com.google.gson.JsonDeserializer;\nimport com.google.gson.JsonElement;\nimport com.google.gson.JsonParseException;\n\nimport java.io.IOException;\nimport java.lang.reflect.Type;\nimport java.text.DateFormat;\nimport java.text.ParseException;\nimport java.text.SimpleDateFormat;\nimport java.util.Date;\nimport java.util.Locale;\nimport java.util.TimeZone;\nimport java.util.concurrent.TimeUnit;"}"}}]},{"role":"tool","name":"edit_file","tool_call_id":"toolu_01GoGz5hJqxP8VK9ATnvuSXv","content":"The apply model made the following changes to the file:

