 // =================== PUBLIC ACCESSORS ===================

 public LiveData<SyncStatus> getSyncStatus() {
 return syncStatusLiveData;
 }

 public LiveData<String> getSyncProgress() {
 return syncProgressLiveData;
 }

 public boolean isSyncInProgress() {
 return isSyncInProgress;
 }

 public long getLastFullSyncTime() {
 return lastFullSyncTime;
 }

 /**
 * Queue an offline action for later sync
 */
 public void queueOfflineAction(String entityType, String entityId, String actionType, String actionData) {
 syncExecutor.execute(() -> {
 OfflineActionEntity action = new OfflineActionEntity(entityType, entityId, actionType, actionData != null ? actionData : "", System.currentTimeMillis(), null);
 offlineActionDao.insertAction(action);
 Log.d(TAG, "Queued offline action: " + actionType + " for " + entityType + " " + entityId);
 });
 }

 /**
 * Force immediate sync if network available
 */
 public CompletableFuture<SyncResult> forceSyncNow() {
 Log.i(TAG, "Force sync requested");
 return performFullSync();
 }

 /**
 * Clean up old completed offline actions and sync metadata
 */
 public void cleanup() {
 syncExecutor.execute(() -> {
 long cutoffTime = System.currentTimeMillis() - (7 * 24 * 60 * 60 * 1000); // 7 days ago
 offlineActionDao.deleteOldCompletedActions(cutoffTime);
 Log.d(TAG, "Cleaned up old offline actions");
 });
 }

 /**
 * Legacy getInstance method for backward compatibility
