import java.util.Date;

/**
 * DTO for trip data from API
 */
public class TripDto {
 private String tripId;
 private String clientId;
 private String status;
 private Date createdAt;
 private Date claimedAt;
 private Date completedAt;
 private SessionInfoDto sessionInfo;

 public TripDto() {}

 public TripDto(String tripId, String clientId, String status, Date createdAt, 
 Date claimedAt, Date completedAt, SessionInfoDto sessionInfo) {
 this.tripId = tripId;
 this.clientId = clientId;
 this.status = status;
 this.createdAt = createdAt;
 this.claimedAt = claimedAt;
 this.completedAt = completedAt;
 this.sessionInfo = sessionInfo;
 }

 public String getTripId() {
 return tripId;
 }

 public void setTripId(String tripId) {
 this.tripId = tripId;
 }

 public String getClientId() {
 return clientId;
 }

 public void setClientId(String clientId) {
 this.clientId = clientId;
 }

 public String getStatus() {
 return status;
 }

 public void setStatus(String status) {
 this.status = status;
 }

 public Date getCreatedAt() {
 return createdAt;
 }

 public void setCreatedAt(Date createdAt) {
 this.createdAt = createdAt;
 }

 public Date getClaimedAt() {
 return claimedAt;
 }

 public void setClaimedAt(Date claimedAt) {
 this.claimedAt = claimedAt;
 }

 public Date getCompletedAt() {
 return completedAt;
 }

 public void setCompletedAt(Date completedAt) {
 this.completedAt = completedAt;
 }

 public SessionInfoDto getSessionInfo() {
 return sessionInfo;
 }

 public void setSessionInfo(SessionInfoDto sessionInfo) {
 this.sessionInfo = sessionInfo;
 }
}"},{"role":"tool","name":"read_file","tool_call_id":"toolu_01VpgcPyNpJQGbu5BpLNnric","content":"package com.clone.EasyDelivery.data.entities;

import androidx.annotation.NonNull;
import androidx.room.ColumnInfo;
import androidx.room.Entity;
import androidx.room.ForeignKey;
import androidx.room.Ignore;
import androidx.room.Index;
import androidx.room.PrimaryKey;

/**
 * Room entity for trip data
 */
@Entity(
 tableName = "trips",
 foreignKeys = {
 @ForeignKey(
 entity = SessionEntity.class,
 parentColumns = "session_id",
 childColumns = "session_id",
 onDelete = ForeignKey.SET_NULL
 )
 },
 indices = {
 @Index(value = "client_id"),
 @Index(value = "session_id"),
 @Index(value = "status"),
 @Index(value = "driver_id")
 }
)
public class TripEntity {

 @PrimaryKey
 @NonNull
 @ColumnInfo(name = "trip_id")
 private String tripId;

 @ColumnInfo(name = "client_id")
 private String clientId;

 @ColumnInfo(name = "status") // "available", "claimed", "in_progress", "completed"
 private String status;

 @ColumnInfo(name = "created_at")
 private long createdAt;

 @ColumnInfo(name = "claimed_at")
 private Long claimedAt;

 @ColumnInfo(name = "started_at")
 private Long startedAt;

 @ColumnInfo(name = "completed_at")
 private Long completedAt;

 // Session info
 @ColumnInfo(name = "session_id")
 private String sessionId;

 @ColumnInfo(name = "driver_id")
 private String driverId;

 @ColumnInfo(name = "vehicle_info")
 private String vehicleInfo;

 // Delivery count for progress tracking
 @ColumnInfo(name = "total_deliveries")
 private int totalDeliveries;

 @ColumnInfo(name = "completed_deliveries")
 private int completedDeliveries;

 // Sync metadata
 @ColumnInfo(name = "synced_at")
 private long syncedAt;

 @ColumnInfo(name = "sync_status")
 private String syncStatus;

 @ColumnInfo(name = "server_version")
 private String serverVersion;

 @ColumnInfo(name = "updated_at")
 private Long updatedAt;

 public TripEntity() {}

 @Ignore
 public TripEntity(String tripId, String clientId, String status, long createdAt) {
 this.tripId = tripId;
 this.clientId = clientId;
 this.status = status;
 this.createdAt = createdAt;
 this.totalDeliveries = 0;
 this.completedDeliveries = 0;
 this.syncStatus = "synced";
 this.syncedAt = System.currentTimeMillis();
 }

 // Getters and setters
 public String getTripId() {
 return tripId;
 }

 public void setTripId(String tripId) {
 this.tripId = tripId;
 }

 public String getClientId() {
 return clientId;
 }

 public void setClientId(String clientId) {
 this.clientId = clientId;
 }

 public String getStatus() {
 return status;
 }

 public void setStatus(String status) {
 this.status = status;
 }

 public long getCreatedAt() {
 return createdAt;
 }

 public void setCreatedAt(long createdAt) {
 this.createdAt = createdAt;
 }

 public Long getClaimedAt() {
 return claimedAt;
 }

 public void setClaimedAt(Long claimedAt) {
 this.claimedAt = claimedAt;
 }

 public Long getStartedAt() {
 return startedAt;
 }

 public void setStartedAt(Long startedAt) {
 this.startedAt = startedAt;
 }

 public Long getCompletedAt() {
 return completedAt;
 }

 public void setCompletedAt(Long completedAt) {
 this.completedAt = completedAt;
 }

 public String getSessionId() {
 return sessionId;
 }

 public void setSessionId(String sessionId) {
