Let me create a unified error handler:"}],"tool_calls":[{"id":"toolu_013orYtukyUgz14NV1PaZEgP","type":"function","function":{"name":"edit_file","arguments":"{"target_file": "app/src/main/java/com/clone/EasyDelivery/util/ErrorHandler.java", "instructions": "I'll create a standardized error handler that consolidates error response handling across the app, reducing duplication in error handling code.", "code_edit": "package com.clone.EasyDelivery.util;\n\nimport android.util.Log;\n\nimport com.clone.EasyDelivery.repository.utils.Resource;\n\nimport java.io.IOException;\nimport java.net.SocketTimeoutException;\nimport java.net.UnknownHostException;\n\n/**\n * Standardized error handler for consistent error processing across the app\n * Consolidates error handling logic to reduce duplication\n */\npublic class ErrorHandler {\n \n private static final String TAG = \"ErrorHandler\";\n \n /**\n * Convert exception to user-friendly error message\n */\n public static String getErrorMessage(Throwable throwable) {\n if (throwable == null) {\n return \"Unknown error occurred\";\n }\n \n if (throwable instanceof UnknownHostException) {\n return \"No internet connection available\";\n }\n \n if (throwable instanceof SocketTimeoutException) {\n return \"Request timed out. Please try again.\";\n }\n \n if (throwable instanceof IOException) {\n return \"Network error. Please check your connection.\";\n }\n \n String message = throwable.getMessage();\n return message != null && !message.isEmpty() ? message : \"An unexpected error occurred\";\n }\n \n /**\n * Get error code from throwable\n */\n public static int getErrorCode(Throwable throwable) {\n if (throwable instanceof UnknownHostException) {\n return -1001; // No internet\n }\n \n if (throwable instanceof SocketTimeoutException) {\n return -1002; // Timeout\n }\n \n if (throwable instanceof IOException) {\n return -1003; // Network error\n }\n \n return -1000; // Generic error\n }\n \n /**\n * Create Resource.error from throwable\n */\n public static <T> Resource<T> handleError(Throwable throwable, T data) {\n String message = getErrorMessage(throwable);\n Log.e(TAG, \"Error handled: \" + message, throwable);\n return Resource.error(message, data);\n }\n \n /**\n * Create Resource.error from message\n */\n public static <T> Resource<T> handleError(String message, T data) {\n Log.e(TAG, \"Error handled: \" + message);\n return Resource.error(message, data);\n }\n \n /**\n * Log and return standardized error\n */\n public static String logAndReturn(String tag, String message, Throwable throwable) {\n String errorMessage = getErrorMessage(throwable);\n Log.e(tag, message + \": \" + errorMessage, throwable);\n return errorMessage;\n }\n}"}"}}]},{"role":"tool","name":"edit_file","tool_call_id":"toolu_013orYtukyUgz14NV1PaZEgP","content":"The apply model made the following changes to the file:

```
@@ -1,1 +1,87 @@
+package com.clone.EasyDelivery.util;

+import android.util.Log;
+
+import com.clone.EasyDelivery.repository.utils.Resource;
+
+import java.io.IOException;
+import java.net.SocketTimeoutException;
+import java.net.UnknownHostException;
+
+/**
+ * Standardized error handler for consistent error processing across the app
+ * Consolidates error handling logic to reduce duplication
+ */
+public class ErrorHandler {
+
+ private static final String TAG = "ErrorHandler";
+
+ /**
+ * Convert exception to user-friendly error message
+ */
+ public static String getErrorMessage(Throwable throwable) {
+ if (throwable == null) {
+ return "Unknown error occurred";
+ }
+
+ if (throwable instanceof UnknownHostException) {
+ return "No internet connection available";
+ }
+
+ if (throwable instanceof SocketTimeoutException) {
+ return "Request timed out. Please try again.";
+ }
+
+ if (throwable instanceof IOException) {
+ return "Network error. Please check your connection.";
+ }
+
+ String message = throwable.getMessage();
+ return message != null && !message.isEmpty() ? message : "An unexpected error occurred";
+ }
+
+ /**
+ * Get error code from throwable
+ */
+ public static int getErrorCode(Throwable throwable) {
+ if (throwable instanceof UnknownHostException) {
+ return -1001; // No internet
+ }
+
+ if (throwable instanceof SocketTimeoutException) {
+ return -1002; // Timeout
+ }
+
+ if (throwable instanceof IOException) {
+ return -1003; // Network error
+ }
+
+ return -1000; // Generic error
+ }
+
+ /**
+ * Create Resource.error from throwable
+ */
+ public static <T> Resource<T> handleError(Throwable throwable, T data) {
+ String message = getErrorMessage(throwable);
+ Log.e(TAG, "Error handled: " + message, throwable);
+ return Resource.error(message, data);
+ }
+
+ /**
+ * Create Resource.error from message
+ */
+ public static <T> Resource<T> handleError(String message, T data) {
+ Log.e(TAG, "Error handled: " + message);
+ return Resource.error(message, data);
+ }
+
+ /**
+ * Log and return standardized error
+ */
+ public static String logAndReturn(String tag, String message, Throwable throwable) {
+ String errorMessage = getErrorMessage(throwable);
+ Log.e(tag, message + ": " + errorMessage, throwable);
+ return errorMessage;
+ }
+}
```

