android {
 compileSdkVersion 34
 namespace 'com.clone.EasyDelivery'

 defaultConfig {
 applicationId 'com.clone.EasyDelivery'
 minSdkVersion 24
 targetSdkVersion 34
 versionCode 1
 versionName "1.0"

 testInstrumentationRunner "androidx.test.runner.AndroidJUnitRunner"

 // API Configuration
 buildConfigField "String", "API_BASE_URL", '"https://delivery-cloud-api-833551875057.africa-south1.run.app/api/"'
