- private static final long CONFLICT_RESOLUTION_TIMEOUT = 30000; // 30 seconds
- 
- // Dependencies injected by Hilt
- private final Context context;
- private final SharedPreferences preferences;
- private final ExecutorService syncExecutor;
- 
- // DAOs
- private final OfflineActionDao offlineActionDao;
- private final TripDao tripDao;
- private final DeliveryDao deliveryDao;
- private final SessionDao sessionDao;
- 
- // API Services
- private final AuthService authService;
- private final TripService tripService;
- private final DeliveryService deliveryService;
- 
- // Sync state
- private final MutableLiveData<SyncStatus> syncStatusLiveData;
- private final MutableLiveData<String> syncProgressLiveData;
- private volatile boolean isSyncInProgress = false;
- private volatile long lastFullSyncTime = 0;
- 
- @Inject
- public SyncManager(@ApplicationContext Context context,
- SharedPreferences preferences,
- ExecutorService executorService,
- OfflineActionDao offlineActionDao,
- TripDao tripDao,
- DeliveryDao deliveryDao, 
- SessionDao sessionDao,
- AuthService authService,
- TripService tripService,
- DeliveryService deliveryService) {
- this.context = context;
- this.preferences = preferences;
- this.syncExecutor = executorService;
- 
- // Initialize DAOs
- this.offlineActionDao = offlineActionDao;
- this.tripDao = tripDao;
- this.deliveryDao = deliveryDao;
- this.sessionDao = sessionDao;
- 
- // Initialize API services
- this.authService = authService;
- this.tripService = tripService;
- this.deliveryService = deliveryService;
- 
- // Initialize sync state
- this.syncStatusLiveData = new MutableLiveData<>(SyncStatus.IDLE);
- this.syncProgressLiveData = new MutableLiveData<>("");
- this.lastFullSyncTime = preferences.getLong("last_full_sync_time", 0);
- 
- Log.i(TAG, "SyncManager initialized with Hilt DI");
- }
- 
- // =================== SYNC OPERATIONS ===================
- 
- /**
- * Perform full synchronization (upload pending changes, download updates)
- */
- public CompletableFuture<SyncResult> performFullSync() {
- if (isSyncInProgress) {
- Log.w(TAG, "Sync already in progress, skipping");
- return CompletableFuture.completedFuture(
- SyncResult.error("Sync already in progress")
- );
- }
- 
- if (!isNetworkAvailable()) {
- Log.w(TAG, "Network not available, skipping sync");
- return CompletableFuture.completedFuture(
- SyncResult.error("Network not available")
- );
- }
- 
- Log.i(TAG, "Starting full synchronization");
- isSyncInProgress = true;
- syncStatusLiveData.postValue(SyncStatus.SYNCING);
- updateSyncProgress("Starting sync...");
- 
- return CompletableFuture.supplyAsync(() -> {
- try {
- // Step 1: Process offline actions queue
- updateSyncProgress("Processing offline actions...");
- SyncResult offlineResult = processOfflineActionsSync();
- if (!offlineResult.isSuccess()) {
- Log.e(TAG, "Offline actions sync failed: " + offlineResult.getErrorMessage());
- return offlineResult;
- }
- 
- // Step 2: Upload local changes
- updateSyncProgress("Uploading local changes...");
- SyncResult uploadResult = uploadLocalChangesSync();
- if (!uploadResult.isSuccess()) {
- Log.e(TAG, "Upload sync failed: " + uploadResult.getErrorMessage());
- return uploadResult;
- }
- 
- // Step 3: Download remote updates
- updateSyncProgress("Downloading updates...");
- SyncResult downloadResult = downloadRemoteUpdatesSync();
- if (!downloadResult.isSuccess()) {
- Log.e(TAG, "Download sync failed: " + downloadResult.getErrorMessage());
- return downloadResult;
- }
- 
- // Step 4: Update sync metadata
- updateSyncProgress("Finalizing...");
- lastFullSyncTime = System.currentTimeMillis();
- preferences.edit()
- .putLong("last_full_sync_time", lastFullSyncTime)
- .apply();
- 
- // Step 5: Mark all entities as synced
- markEntitiesAsSynced();
- 
- updateSyncProgress("Sync completed successfully");
- Log.i(TAG, "Full synchronization completed successfully");
- 
- return SyncResult.success("Full sync completed", 
- offlineResult.getSyncedCount() + uploadResult.getSyncedCount() + downloadResult.getSyncedCount());
- 
- } catch (Exception e) {
- Log.e(TAG, "Full sync failed with exception", e);
- return SyncResult.error("Sync failed: " + e.getMessage());
- 
- } finally {
- isSyncInProgress = false;
- syncStatusLiveData.postValue(SyncStatus.IDLE);
- }
- }, syncExecutor);
- }
- 
- /**
- * Process offline actions queue (create, update, delete operations)
- */
- private SyncResult processOfflineActionsSync() {
- try {
- List<OfflineActionEntity> pendingActions = offlineActionDao.getPendingActions();
- Log.i(TAG, "Processing " + pendingActions.size() + " offline actions");
- 
- AtomicInteger successCount = new AtomicInteger(0);
- List<String> errors = new ArrayList<>();
- 
- for (OfflineActionEntity action : pendingActions) {
- try {
- boolean success = processOfflineAction(action);
- if (success) {
- // Mark action as completed
- offlineActionDao.markActionCompleted(action.getId(), System.currentTimeMillis());
- successCount.incrementAndGet();
- } else {
- // Increment retry count
- long nextRetryTime = System.currentTimeMillis() + (60 * 1000); // Retry in 1 minute
- offlineActionDao.incrementRetryCount(action.getId(), System.currentTimeMillis(), nextRetryTime, "Sync failed");
- if (action.getRetryCount() >= MAX_RETRY_ATTEMPTS) {
- offlineActionDao.markActionFailed(action.getId(), "Max retries exceeded");
- }
- errors.add("Failed to process action: " + action.getId());
- }
- } catch (Exception e) {
- Log.e(TAG, "Error processing offline action: " + action.getId(), e);
- long nextRetryTime = System.currentTimeMillis() + (60 * 1000); // Retry in 1 minute
- offlineActionDao.incrementRetryCount(action.getId(), System.currentTimeMillis(), nextRetryTime, e.getMessage());
- errors.add("Exception processing action " + action.getId() + ": " + e.getMessage());
- }
- }
- 
- if (errors.isEmpty()) {
- return SyncResult.success("All offline actions processed", successCount.get());
- } else {
- return SyncResult.partialSuccess("Some actions failed", successCount.get(), errors);
- }
- 
- } catch (Exception e) {
- Log.e(TAG, "Failed to process offline actions", e);
- return SyncResult.error("Failed to process offline actions: " + e.getMessage());
- }
- }
- 
- /**
- * Upload local changes that haven't been synced
- */
- private SyncResult uploadLocalChangesSync() {
- try {
- AtomicInteger totalUploaded = new AtomicInteger(0);
- List<String> errors = new ArrayList<>();
- 
- // Upload trips
- List<TripEntity> unsyncedTrips = tripDao.getUnsyncedTrips();
- Log.i(TAG, "Uploading " + unsyncedTrips.size() + " unsynced trips");
- 
- for (TripEntity trip : unsyncedTrips) {
- try {
- boolean success = uploadTrip(trip);
- if (success) {
- totalUploaded.incrementAndGet();
- } else {
- errors.add("Failed to upload trip: " + trip.getTripId());
- }
- } catch (Exception e) {
- Log.e(TAG, "Error uploading trip: " + trip.getTripId(), e);
- errors.add("Exception uploading trip " + trip.getTripId() + ": " + e.getMessage());
- }
- }
- 
- // Upload deliveries
- List<DeliveryEntity> unsyncedDeliveries = deliveryDao.getUnsyncedDeliveries();
- Log.i(TAG, "Uploading " + unsyncedDeliveries.size() + " unsynced deliveries");
- 
- for (DeliveryEntity delivery : unsyncedDeliveries) {
- try {
- boolean success = uploadDelivery(delivery);
- if (success) {
- totalUploaded.incrementAndGet();
- } else {
- errors.add("Failed to upload delivery: " + delivery.getDeliveryId());
- }
- } catch (Exception e) {
- Log.e(TAG, "Error uploading delivery: " + delivery.getDeliveryId(), e);
- errors.add("Exception uploading delivery " + delivery.getDeliveryId() + ": " + e.getMessage());
- }
- }
- 
- if (errors.isEmpty()) {
- return SyncResult.success("Local changes uploaded", totalUploaded.get());
- } else {
- return SyncResult.partialSuccess("Some uploads failed", totalUploaded.get(), errors);
- }
- 
- } catch (Exception e) {
- Log.e(TAG, "Failed to upload local changes", e);
- return SyncResult.error("Failed to upload local changes: " + e.getMessage());
- }
- }
- 
- /**
- * Download remote updates since last sync
- */
- private SyncResult downloadRemoteUpdatesSync() {
- try {
- AtomicInteger totalDownloaded = new AtomicInteger(0);
- List<String> errors = new ArrayList<>();
- 
- // Download trips updated since last sync
- try {
- int downloadedTrips = downloadUpdatedTrips();
- totalDownloaded.addAndGet(downloadedTrips);
- Log.i(TAG, "Downloaded " + downloadedTrips + " trip updates");
- } catch (Exception e) {
- Log.e(TAG, "Failed to download trip updates", e);
- errors.add("Failed to download trips: " + e.getMessage());
- }
- 
- // Download deliveries updated since last sync
- try {
- int downloadedDeliveries = downloadUpdatedDeliveries();
- totalDownloaded.addAndGet(downloadedDeliveries);
- Log.i(TAG, "Downloaded " + downloadedDeliveries + " delivery updates");
- } catch (Exception e) {
- Log.e(TAG, "Failed to download delivery updates", e);
- errors.add("Failed to download deliveries: " + e.getMessage());
- }
- 
- if (errors.isEmpty()) {
- return SyncResult.success("Remote updates downloaded", totalDownloaded.get());
- } else {
- return SyncResult.partialSuccess("Some downloads failed", totalDownloaded.get(), errors);
- }
- 
- } catch (Exception e) {
- Log.e(TAG, "Failed to download remote updates", e);
- return SyncResult.error("Failed to download remote updates: " + e.getMessage());
- }
- }
- 
- // =================== OFFLINE ACTION PROCESSING ===================
- 
- private boolean processOfflineAction(OfflineActionEntity action) {
- Log.d(TAG, "Processing offline action: " + action.getActionType() + " for " + action.getEntityType());
- 
- switch (action.getEntityType()) {
- case "TRIP":
- return processTripAction(action);
- case "DELIVERY":
- return processDeliveryAction(action);
- case "SESSION":
- return processSessionAction(action);
- default:
- Log.w(TAG, "Unknown entity type for offline action: " + action.getEntityType());
- return false;
- }
- }
- 
- private boolean processTripAction(OfflineActionEntity action) {
- try {
- TripEntity trip = tripDao.getTrip(action.getEntityId());
- if (trip == null) {
- Log.w(TAG, "Trip not found for offline action: " + action.getEntityId());
- return false;
- }
- 
- switch (action.getActionType()) {
- case "CREATE":
- case "UPDATE":
- return uploadTrip(trip);
- case "DELETE":
- // Handle trip deletion via API
- return deleteTripOnServer(action.getEntityId());
- default:
- Log.w(TAG, "Unknown action type for trip: " + action.getActionType());
- return false;
- }
- } catch (Exception e) {
- Log.e(TAG, "Error processing trip action", e);
- return false;
- }
- }
- 
- private boolean processDeliveryAction(OfflineActionEntity action) {
- try {
- DeliveryEntity delivery = deliveryDao.getDelivery(action.getEntityId());
- if (delivery == null) {
- Log.w(TAG, "Delivery not found for offline action: " + action.getEntityId());
- return false;
- }
- 
- switch (action.getActionType()) {
- case "CREATE":
- case "UPDATE":
- return uploadDelivery(delivery);
- case "DELETE":
- // Handle delivery deletion via API
- return deleteDeliveryOnServer(action.getEntityId());
- default:
- Log.w(TAG, "Unknown action type for delivery: " + action.getActionType());
- return false;
- }
- } catch (Exception e) {
- Log.e(TAG, "Error processing delivery action", e);
- return false;
- }
- }
- 
- private boolean processSessionAction(OfflineActionEntity action) {
- try {
- SessionEntity session = sessionDao.getSession(action.getEntityId());
- if (session == null) {
- Log.w(TAG, "Session not found for offline action: " + action.getEntityId());
- return false;
- }
- 
- switch (action.getActionType()) {
- case "END_SESSION":
- return endSessionOnServer(action.getEntityId());
- default:
- Log.w(TAG, "Unknown action type for session: " + action.getActionType());
- return false;
- }
- } catch (Exception e) {
- Log.e(TAG, "Error processing session action", e);
- return false;
- }
- }
- 
- // =================== UTILITY METHODS ===================
- 
- private void updateSyncProgress(String message) {
- syncProgressLiveData.postValue(message);
- Log.d(TAG, "Sync progress: " + message);
- }
- 
- private void markEntitiesAsSynced() {
- syncExecutor.execute(() -> {
- // Mark entities as synced - these methods would need to be added to DAOs
- // For now, we'll skip this step as the entities are marked individually
- Log.d(TAG, "Entities sync status updated individually during sync process");
- });
- }
- 
- private boolean isNetworkAvailable() {
- ConnectivityManager connectivityManager = 
- (ConnectivityManager) context.getSystemService(Context.CONNECTIVITY_SERVICE);
- 
- if (connectivityManager != null) {
- NetworkInfo activeNetworkInfo = connectivityManager.getActiveNetworkInfo();
- return activeNetworkInfo != null && activeNetworkInfo.isConnected();
- }
- 
- return false;
- }
