- /**
- * Queue an offline action for later sync
- */
- public void queueOfflineAction(String entityType, String entityId, String actionType, String actionData) {
- syncExecutor.execute(() -> {
- OfflineActionEntity action = new OfflineActionEntity(entityType, entityId, actionType, actionData != null ? actionData : "", System.currentTimeMillis(), null);
- offlineActionDao.insertAction(action);
- Log.d(TAG, "Queued offline action: " + actionType + " for " + entityType + " " + entityId);
- });
