-import com.clone.EasyDelivery.sync.models.ConflictResolution;
-import com.clone.EasyDelivery.sync.models.ConflictStrategy;
-
-/**
- * Handles conflict resolution when the same data has been modified both locally and on the server
- */
-public class ConflictResolver {
- 
- private static final String TAG = "ConflictResolver";
- 
- private final Context context;
- 
- public ConflictResolver(Context context) {
- this.context = context.getApplicationContext();
- }
- 
- // =================== TRIP CONFLICT RESOLUTION ===================
- 
- /**
- * Resolve conflicts between local and server trip data
- */
- public ConflictResolution<TripEntity> resolveTripConflict(
- TripEntity localTrip, 
- TripEntity serverTrip, 
- ConflictStrategy strategy) {
- 
- Log.i(TAG, "Resolving trip conflict for ID: " + localTrip.getId() + 
- " using strategy: " + strategy);
- 
- switch (strategy) {
- case SERVER_WINS:
- return ConflictResolution.useServer(serverTrip, "Server version selected");
- 
- case CLIENT_WINS:
- return ConflictResolution.useLocal(localTrip, "Local version selected");
- 
- case LAST_WRITE_WINS:
- return resolveTripByTimestamp(localTrip, serverTrip);
- 
- case MERGE:
- return mergeTripData(localTrip, serverTrip);
- 
- case USER_CHOICE:
- // For now, default to last write wins - UI implementation would prompt user
- Log.w(TAG, "User choice not implemented, falling back to last write wins");
- return resolveTripByTimestamp(localTrip, serverTrip);
- 
- default:
- Log.w(TAG, "Unknown conflict strategy: " + strategy + ", using LAST_WRITE_WINS");
- return resolveTripByTimestamp(localTrip, serverTrip);
- }
- }
- 
- /**
- * Resolve trip conflict using timestamp comparison
- */
- private ConflictResolution<TripEntity> resolveTripByTimestamp(TripEntity localTrip, TripEntity serverTrip) {
- // Compare modification timestamps
- long localModified = localTrip.getUpdatedAt() != null ? localTrip.getUpdatedAt() : localTrip.getCreatedAt();
- long serverModified = serverTrip.getUpdatedAt() != null ? serverTrip.getUpdatedAt() : serverTrip.getCreatedAt();
- 
- if (localModified > serverModified) {
- Log.d(TAG, "Local trip is newer, keeping local version");
- return ConflictResolution.useLocal(localTrip, 
- "Local version is newer (local: " + localModified + ", server: " + serverModified + ")");
- } else if (serverModified > localModified) {
- Log.d(TAG, "Server trip is newer, using server version");
- return ConflictResolution.useServer(serverTrip, 
- "Server version is newer (server: " + serverModified + ", local: " + localModified + ")");
- } else {
- // Same timestamp, prefer server version for consistency
- Log.d(TAG, "Same timestamp, preferring server version");
- return ConflictResolution.useServer(serverTrip, "Same timestamp, preferring server");
- }
- }
- 
- /**
- * Merge trip data intelligently
- */
- private ConflictResolution<TripEntity> mergeTripData(TripEntity localTrip, TripEntity serverTrip) {
- Log.d(TAG, "Merging trip data for ID: " + localTrip.getId());
-
- // Create a new merged trip entity
- TripEntity merged = new TripEntity(
- localTrip.getTripId(),
- localTrip.getClientId(),
- serverTrip.getStatus() != null ? serverTrip.getStatus() : localTrip.getStatus(),
- Math.max(localTrip.getCreatedAt(), serverTrip.getCreatedAt())
- );
- 
- // Use the most recent timestamp for each field that might be updated independently
- merged.setStatus(serverTrip.getStatus() != null ? serverTrip.getStatus() : localTrip.getStatus());
- merged.setSessionId(serverTrip.getSessionId() != null ? serverTrip.getSessionId() : localTrip.getSessionId());
- merged.setDriverId(serverTrip.getDriverId() != null ? serverTrip.getDriverId() : localTrip.getDriverId());
- merged.setVehicleInfo(serverTrip.getVehicleInfo() != null ? serverTrip.getVehicleInfo() : localTrip.getVehicleInfo());
-
- // Use server data for fields that shouldn't change once set
- merged.setStartLocation(serverTrip.getStartLocation() != null ? serverTrip.getStartLocation() : localTrip.getStartLocation());
- merged.setEndLocation(serverTrip.getEndLocation() != null ? serverTrip.getEndLocation() : localTrip.getEndLocation());
- merged.setEstimatedDistance(serverTrip.getEstimatedDistance() != null ? serverTrip.getEstimatedDistance() : localTrip.getEstimatedDistance());
-
- // For time fields, use the most recent non-null values
- merged.setStartedAt(mergeTimestamp(localTrip.getStartedAt(), serverTrip.getStartedAt()));
- merged.setEndedAt(mergeTimestamp(localTrip.getEndedAt(), serverTrip.getEndedAt()));
- 
- // Use the latest timestamps
- merged.setCreatedAt(Math.min(localTrip.getCreatedAt(), serverTrip.getCreatedAt())); // Earlier creation
- merged.setUpdatedAt(Math.max(
- localTrip.getUpdatedAt() != null ? localTrip.getUpdatedAt() : localTrip.getCreatedAt(),
- serverTrip.getUpdatedAt() != null ? serverTrip.getUpdatedAt() : serverTrip.getCreatedAt()
- )); // Later update
- 
- // Preserve sync metadata from server
- merged.setServerVersion(serverTrip.getServerVersion());
