- 
- default:
- Log.w(TAG, "Unknown conflict strategy: " + strategy + ", using LAST_WRITE_WINS");
- return resolveDeliveryByTimestamp(localDelivery, serverDelivery);
- }
- }
- 
- /**
- * Resolve delivery conflict using timestamp comparison
- */
- private ConflictResolution<DeliveryEntity> resolveDeliveryByTimestamp(DeliveryEntity localDelivery, DeliveryEntity serverDelivery) {
- // Compare modification timestamps
- long localModified = localDelivery.getUpdatedAt() != null ? localDelivery.getUpdatedAt() : localDelivery.getCreatedAt();
- long serverModified = serverDelivery.getUpdatedAt() != null ? serverDelivery.getUpdatedAt() : serverDelivery.getCreatedAt();
- 
- if (localModified > serverModified) {
- Log.d(TAG, "Local delivery is newer, keeping local version");
- return ConflictResolution.useLocal(localDelivery, 
- "Local version is newer (local: " + localModified + ", server: " + serverModified + ")");
- } else if (serverModified > localModified) {
- Log.d(TAG, "Server delivery is newer, using server version");
- return ConflictResolution.useServer(serverDelivery, 
- "Server version is newer (server: " + serverModified + ", local: " + localModified + ")");
- } else {
- // Same timestamp, prefer server version for consistency
- Log.d(TAG, "Same timestamp, preferring server version");
- return ConflictResolution.useServer(serverDelivery, "Same timestamp, preferring server");
- }
- }
- 
- /**
- * Merge delivery data intelligently
- */
- private ConflictResolution<DeliveryEntity> mergeDeliveryData(DeliveryEntity localDelivery, DeliveryEntity serverDelivery) {
- Log.d(TAG, "Merging delivery data for ID: " + localDelivery.getId());
- 
- // Create a new merged delivery
- DeliveryEntity merged = new DeliveryEntity(
- localDelivery.getId(),
- localDelivery.getTripId(),
- localDelivery.getOrderNumber() != null ? localDelivery.getOrderNumber() : "unknown",
- localDelivery.getCustomerName() != null ? localDelivery.getCustomerName() : "unknown",
- localDelivery.getAddress() != null ? localDelivery.getAddress() : "unknown",
- localDelivery.getQuantityExpected()
- );
- 
