- // Use server data for fields that shouldn't change once set
- merged.setCustomerPhone(serverDelivery.getCustomerPhone() != null ? serverDelivery.getCustomerPhone() : localDelivery.getCustomerPhone());
- merged.setDeliveryInstructions(serverDelivery.getDeliveryInstructions() != null ? serverDelivery.getDeliveryInstructions() : localDelivery.getDeliveryInstructions());
- merged.setEstimatedDeliveryTime(serverDelivery.getEstimatedDeliveryTime() != null ? serverDelivery.getEstimatedDeliveryTime() : localDelivery.getEstimatedDeliveryTime());
- 
- // For delivery-specific fields, prefer the most recent updates
- merged.setActualDeliveryTime(mergeTimestamp(localDelivery.getActualDeliveryTime(), serverDelivery.getActualDeliveryTime()));
- merged.setDeliveryNotes(mergeString(localDelivery.getDeliveryNotes(), serverDelivery.getDeliveryNotes(), 
- localDelivery.getUpdatedAt(), serverDelivery.getUpdatedAt()));
- merged.setProofOfDeliveryPath(mergeString(localDelivery.getProofOfDeliveryPath(), serverDelivery.getProofOfDeliveryPath(),
- localDelivery.getUpdatedAt(), serverDelivery.getUpdatedAt()));
- 
- // Use the latest timestamps
- merged.setCreatedAt(Math.min(localDelivery.getCreatedAt(), serverDelivery.getCreatedAt()));
- merged.setUpdatedAt(Math.max(
- localDelivery.getUpdatedAt() != null ? localDelivery.getUpdatedAt() : localDelivery.getCreatedAt(),
- serverDelivery.getUpdatedAt() != null ? serverDelivery.getUpdatedAt() : serverDelivery.getCreatedAt()
- ));
- 
- // Preserve sync metadata from server
- merged.setServerVersion(serverDelivery.getServerVersion());
- merged.markAsSynced();
- 
- Log.d(TAG, "Delivery merge completed - Status: " + merged.getStatus());
- return ConflictResolution.useMerged(merged, "Data merged from both versions");
- }
- 
- // =================== UTILITY METHODS ===================
- 
- /**
- * Merge status fields, preferring the more progressed status
- */
- private String mergeStatus(String localStatus, String serverStatus) {
- if (localStatus == null) return serverStatus;
- if (serverStatus == null) return localStatus;
- if (localStatus.equals(serverStatus)) return localStatus;
- 
- // Define status progression order
- String[] statusOrder = {"PENDING", "ASSIGNED", "IN_PROGRESS", "DELIVERED", "FAILED", "CANCELLED"};
- 
- int localIndex = getStatusIndex(localStatus, statusOrder);
- int serverIndex = getStatusIndex(serverStatus, statusOrder);
- 
- // Return the status that's further in progression
- if (localIndex > serverIndex) {
- Log.d(TAG, "Local status '" + localStatus + "' is more progressed than server '" + serverStatus + "'");
- return localStatus;
- } else {
- Log.d(TAG, "Server status '" + serverStatus + "' is more progressed than local '" + localStatus + "'");
- return serverStatus;
- }
- }
- 
- private int getStatusIndex(String status, String[] statusOrder) {
- for (int i = 0; i < statusOrder.length; i++) {
- if (statusOrder[i].equals(status)) {
- return i;
- }
- }
- return -1; // Unknown status, treat as least progressed
- }
- 
- /**
- * Merge timestamp fields, preferring non-null values and later timestamps
- */
- private Long mergeTimestamp(Long localTimestamp, Long serverTimestamp) {
- if (localTimestamp == null) return serverTimestamp;
- if (serverTimestamp == null) return localTimestamp;
- 
- // Return the later timestamp
- return Math.max(localTimestamp, serverTimestamp);
- }
- 
- /**
- * Merge string fields based on which version was updated more recently
- */
- private String mergeString(String localValue, String serverValue, Long localUpdated, Long serverUpdated) {
- if (localValue == null) return serverValue;
- if (serverValue == null) return localValue;
- if (localValue.equals(serverValue)) return localValue;
- 
- // If we have update timestamps, use the more recent value
- if (localUpdated != null && serverUpdated != null) {
- return localUpdated > serverUpdated ? localValue : serverValue;
- }
- 
- // Default to server value if no timestamp info
- return serverValue;
- }
- 
- /**
- * Get the default conflict resolution strategy
- * In production, this could be configurable per client or user preference
- */
- public ConflictStrategy getDefaultStrategy() {
- return ConflictStrategy.MERGE; // Prefer intelligent merging
- }
- 
- /**
- * Determine if automatic resolution is possible for the given conflict
- */
- public boolean canAutoResolve(String entityType, ConflictStrategy strategy) {
- // All strategies except USER_CHOICE can be auto-resolved
- return strategy != ConflictStrategy.USER_CHOICE;
- }
- 
- /**
- * Log conflict resolution details for debugging
- */
- private void logResolution(String entityType, String entityId, ConflictStrategy strategy, String resolution) {
- Log.i(TAG, String.format("Conflict resolved - Type: %s, ID: %s, Strategy: %s, Resolution: %s", 
- entityType, entityId, strategy, resolution));
- }
-}

