-/**
- * Result of conflict resolution containing the resolved data and resolution details
- * 
- * @param <T> The type of entity being resolved (TripEntity, DeliveryEntity, etc.)
- */
-public class ConflictResolution<T> {
- 
- public enum ResolutionType {
- USE_LOCAL, // Use the local version
- USE_SERVER, // Use the server version 
- USE_MERGED, // Use a merged version
- REQUIRES_USER // Requires user intervention
- }
- 
- private final ResolutionType resolutionType;
- private final T resolvedEntity;
- private final String reason;
- private final long timestamp;
- 
- private ConflictResolution(ResolutionType resolutionType, T resolvedEntity, String reason) {
- this.resolutionType = resolutionType;
- this.resolvedEntity = resolvedEntity;
- this.reason = reason;
- this.timestamp = System.currentTimeMillis();
- }
- 
- /**
- * Create a resolution that uses the local version
- */
- public static <T> ConflictResolution<T> useLocal(T localEntity, String reason) {
- return new ConflictResolution<>(ResolutionType.USE_LOCAL, localEntity, reason);
- }
- 
- /**
- * Create a resolution that uses the server version
- */
- public static <T> ConflictResolution<T> useServer(T serverEntity, String reason) {
- return new ConflictResolution<>(ResolutionType.USE_SERVER, serverEntity, reason);
- }
- 
- /**
- * Create a resolution that uses a merged version
- */
- public static <T> ConflictResolution<T> useMerged(T mergedEntity, String reason) {
- return new ConflictResolution<>(ResolutionType.USE_MERGED, mergedEntity, reason);
- }
- 
- /**
- * Create a resolution that requires user intervention
- */
- public static <T> ConflictResolution<T> requiresUser(String reason) {
- return new ConflictResolution<>(ResolutionType.REQUIRES_USER, null, reason);
- }
- 
- // Getters
- 
- public ResolutionType getResolutionType() {
- return resolutionType;
- }
- 
- public T getResolvedEntity() {
- return resolvedEntity;
- }
- 
- public String getReason() {
- return reason;
- }
- 
- public long getTimestamp() {
- return timestamp;
- }
- 
- // Utility methods
- 
- public boolean isResolved() {
- return resolutionType != ResolutionType.REQUIRES_USER && resolvedEntity != null;
- }
- 
- public boolean requiresUserInput() {
- return resolutionType == ResolutionType.REQUIRES_USER;
- }
- 
- public boolean usedLocalVersion() {
- return resolutionType == ResolutionType.USE_LOCAL;
- }
- 
- public boolean usedServerVersion() {
- return resolutionType == ResolutionType.USE_SERVER;
- }
- 
- public boolean usedMergedVersion() {
- return resolutionType == ResolutionType.USE_MERGED;
- }
- 
- /**
- * Get a human-readable summary of the resolution
- */
- public String getSummary() {
- switch (resolutionType) {
- case USE_LOCAL:
- return "Used local version: " + reason;
- case USE_SERVER:
- return "Used server version: " + reason;
- case USE_MERGED:
- return "Used merged version: " + reason;
- case REQUIRES_USER:
- return "Requires user choice: " + reason;
- default:
- return "Unknown resolution: " + reason;
- }
- }
- 
- @Override
- public String toString() {
