 /**
 * Convert DeliveryEntity to legacy Delivery model for existing UI
 * Maintains compatibility with existing HeaderAdapter and other components
 */
 public List<com.clone.EasyDelivery.Model.Delivery> convertToLegacyDeliveries() {
 UiState<List<DeliveryEntity>> state = deliveriesStateLiveData.getValue();
 List<com.clone.EasyDelivery.Model.Delivery> legacyDeliveries = new ArrayList<>();

 if (state != null && state.isSuccess() && state.hasData()) {
 for (DeliveryEntity entity : state.getData()) {
 com.clone.EasyDelivery.Model.Delivery legacy = new com.clone.EasyDelivery.Model.Delivery();

 // Map fields from new entity to legacy model
 legacy.setDocument(entity.getDeliveryId()); // Using entity ID as document
 legacy.setCustomerName(entity.getCustomerName());
 legacy.setDeliveryAddress(entity.getDeliveryAddress());
 legacy.setCustomerPhone(entity.getCustomerPhone());
 legacy.setDeliveryInstructions(entity.getDeliveryInstructions());
 legacy.setNumberOfParcels(getParcelCountFromEntity(entity));

 // Map status
 legacy.setStatus(entity.getStatus());

 // Map timestamps
 if (entity.getEstimatedDeliveryTime() != null) {
 legacy.setEstimatedDeliveryTime(entity.getEstimatedDeliveryTime());
 }
 if (entity.getActualDeliveryTime() != null) {
 legacy.setActualDeliveryTime(entity.getActualDeliveryTime());
 }

 legacyDeliveries.add(legacy);
 }
 }

 Log.d(TAG, "Converted " + legacyDeliveries.size() + " entities to legacy format");
 return legacyDeliveries;
 }

