 List<DeliveryEntity> filtered = new java.util.ArrayList<>();
 for (DeliveryEntity delivery : deliveries) {
 if (delivery.getCustomerName().toLowerCase().contains(searchTerm)) {
 filtered.add(delivery);
 }
 }
 return filtered;
 }
);
