 return Resource.error("Failed to start trip: " + e.getMessage(), null);
 }
 }, executor);
 }

 /**
 * Complete a trip
 */
 public CompletableFuture<Resource<TripEntity>> completeTrip(String tripId) {
 Log.i(TAG, "Completing trip: " + tripId);

 return CompletableFuture.supplyAsync(() -> {
