+ return null;
+ }
+
+ try {
+ // Try ISO 8601 format with milliseconds first
+ Date date = ISO_DATE_FORMAT.parse(createdAt);
+ return date.getTime();
+ } catch (ParseException e1) {
+ try {
+ // Try ISO 8601 format without milliseconds
