-package com.clone.EasyDelivery.sync;
-
-import android.content.Context;
-import android.util.Log;
-
-import com.clone.EasyDelivery.data.entities.DeliveryEntity;
-import com.clone.EasyDelivery.data.entities.TripEntity;
-import com.clone.EasyDelivery.sync.models.ConflictResolution;
-import com.clone.EasyDelivery.sync.models.ConflictStrategy;
-
-/**
- * Handles conflict resolution when the same data has been modified both locally and on the server
- */
-public class ConflictResolver {
- 
- private static final String TAG = "ConflictResolver";
- 
- private final Context context;
- 
- public ConflictResolver(Context context) {
- this.context = context.getApplicationContext();
- }
- 
- // =================== TRIP CONFLICT RESOLUTION ===================
- 
- /**
- * Resolve conflicts between local and server trip data
- */
- public ConflictResolution<TripEntity> resolveTripConflict(
- TripEntity localTrip, 
- TripEntity serverTrip, 
- ConflictStrategy strategy) {
- 
- Log.i(TAG, "Resolving trip conflict for ID: " + localTrip.getId() + 
- " using strategy: " + strategy);
- 
- switch (strategy) {
- case SERVER_WINS:
- return ConflictResolution.useServer(serverTrip, "Server version selected");
- 
- case CLIENT_WINS:
- return ConflictResolution.useLocal(localTrip, "Local version selected");
- 
- case LAST_WRITE_WINS:
- return resolveTripByTimestamp(localTrip, serverTrip);
- 
- case MERGE:
- return mergeTripData(localTrip, serverTrip);
- 
- case USER_CHOICE:
- // For now, default to last write wins - UI implementation would prompt user
- Log.w(TAG, "User choice not implemented, falling back to last write wins");
- return resolveTripByTimestamp(localTrip, serverTrip);
- 
- default:
- Log.w(TAG, "Unknown conflict strategy: " + strategy + ", using LAST_WRITE_WINS");
- return resolveTripByTimestamp(localTrip, serverTrip);
- }
- }
- 
- /**
- * Resolve trip conflict using timestamp comparison
- */
- private ConflictResolution<TripEntity> resolveTripByTimestamp(TripEntity localTrip, TripEntity serverTrip) {
- // Compare modification timestamps
- long localModified = localTrip.getUpdatedAt() != null ? localTrip.getUpdatedAt() : localTrip.getCreatedAt();
- long serverModified = serverTrip.getUpdatedAt() != null ? serverTrip.getUpdatedAt() : serverTrip.getCreatedAt();
- 
- if (localModified > serverModified) {
- Log.d(TAG, "Local trip is newer, keeping local version");
- return ConflictResolution.useLocal(localTrip, 
- "Local version is newer (local: " + localModified + ", server: " + serverModified + ")");
- } else if (serverModified > localModified) {
- Log.d(TAG, "Server trip is newer, using server version");
- return ConflictResolution.useServer(serverTrip, 
- "Server version is newer (server: " + serverModified + ", local: " + localModified + ")");
- } else {
- // Same timestamp, prefer server version for consistency
- Log.d(TAG, "Same timestamp, preferring server version");
- return ConflictResolution.useServer(serverTrip, "Same timestamp, preferring server");
- }
- }
- 
- /**
- * Merge trip data intelligently
- */
- private ConflictResolution<TripEntity> mergeTripData(TripEntity localTrip, TripEntity serverTrip) {
- Log.d(TAG, "Merging trip data for ID: " + localTrip.getId());
-
- // Create a new merged trip entity
- TripEntity merged = new TripEntity(
- localTrip.getTripId(),
- localTrip.getClientId(),
- serverTrip.getStatus() != null ? serverTrip.getStatus() : localTrip.getStatus(),
- Math.max(localTrip.getCreatedAt(), serverTrip.getCreatedAt())
- );
- 
- // Use the most recent timestamp for each field that might be updated independently
- merged.setStatus(serverTrip.getStatus() != null ? serverTrip.getStatus() : localTrip.getStatus());
- merged.setSessionId(serverTrip.getSessionId() != null ? serverTrip.getSessionId() : localTrip.getSessionId());
- merged.setDriverId(serverTrip.getDriverId() != null ? serverTrip.getDriverId() : localTrip.getDriverId());
- merged.setVehicleInfo(serverTrip.getVehicleInfo() != null ? serverTrip.getVehicleInfo() : localTrip.getVehicleInfo());
-
- // Use server data for fields that shouldn't change once set
- merged.setStartLocation(serverTrip.getStartLocation() != null ? serverTrip.getStartLocation() : localTrip.getStartLocation());
- merged.setEndLocation(serverTrip.getEndLocation() != null ? serverTrip.getEndLocation() : localTrip.getEndLocation());
- merged.setEstimatedDistance(serverTrip.getEstimatedDistance() != null ? serverTrip.getEstimatedDistance() : localTrip.getEstimatedDistance());
-
- // For time fields, use the most recent non-null values
- merged.setStartedAt(mergeTimestamp(localTrip.getStartedAt(), serverTrip.getStartedAt()));
- merged.setEndedAt(mergeTimestamp(localTrip.getEndedAt(), serverTrip.getEndedAt()));
- 
- // Use the latest timestamps
- merged.setCreatedAt(Math.min(localTrip.getCreatedAt(), serverTrip.getCreatedAt())); // Earlier creation
- merged.setUpdatedAt(Math.max(
- localTrip.getUpdatedAt() != null ? localTrip.getUpdatedAt() : localTrip.getCreatedAt(),
- serverTrip.getUpdatedAt() != null ? serverTrip.getUpdatedAt() : serverTrip.getCreatedAt()
- )); // Later update
- 
- // Preserve sync metadata from server
- merged.setServerVersion(serverTrip.getServerVersion());
- merged.markAsSynced();
- 
- Log.d(TAG, "Trip merge completed - Status: " + merged.getStatus());
- return ConflictResolution.useMerged(merged, "Data merged from both versions");
- }
- 
- // =================== DELIVERY CONFLICT RESOLUTION ===================
- 
- /**
- * Resolve conflicts between local and server delivery data
- */
- public ConflictResolution<DeliveryEntity> resolveDeliveryConflict(
- DeliveryEntity localDelivery, 
- DeliveryEntity serverDelivery, 
- ConflictStrategy strategy) {
- 
- Log.i(TAG, "Resolving delivery conflict for ID: " + localDelivery.getId() + 
- " using strategy: " + strategy);
- 
- switch (strategy) {
- case SERVER_WINS:
- return ConflictResolution.useServer(serverDelivery, "Server version selected");
- 
- case CLIENT_WINS:
- return ConflictResolution.useLocal(localDelivery, "Local version selected");
- 
- case LAST_WRITE_WINS:
- return resolveDeliveryByTimestamp(localDelivery, serverDelivery);
- 
- case MERGE:
- return mergeDeliveryData(localDelivery, serverDelivery);
- 
- case USER_CHOICE:
- // For now, default to last write wins - UI implementation would prompt user
- Log.w(TAG, "User choice not implemented, falling back to last write wins");
- return resolveDeliveryByTimestamp(localDelivery, serverDelivery);
- 
- default:
- Log.w(TAG, "Unknown conflict strategy: " + strategy + ", using LAST_WRITE_WINS");
- return resolveDeliveryByTimestamp(localDelivery, serverDelivery);
- }
- }
- 
- /**
- * Resolve delivery conflict using timestamp comparison
- */
- private ConflictResolution<DeliveryEntity> resolveDeliveryByTimestamp(DeliveryEntity localDelivery, DeliveryEntity serverDelivery) {
- // Compare modification timestamps
- long localModified = localDelivery.getUpdatedAt() != null ? localDelivery.getUpdatedAt() : localDelivery.getCreatedAt();
- long serverModified = serverDelivery.getUpdatedAt() != null ? serverDelivery.getUpdatedAt() : serverDelivery.getCreatedAt();
- 
- if (localModified > serverModified) {
- Log.d(TAG, "Local delivery is newer, keeping local version");
- return ConflictResolution.useLocal(localDelivery, 
- "Local version is newer (local: " + localModified + ", server: " + serverModified + ")");
- } else if (serverModified > localModified) {
- Log.d(TAG, "Server delivery is newer, using server version");
- return ConflictResolution.useServer(serverDelivery, 
- "Server version is newer (server: " + serverModified + ", local: " + localModified + ")");
- } else {
- // Same timestamp, prefer server version for consistency
- Log.d(TAG, "Same timestamp, preferring server version");
- return ConflictResolution.useServer(serverDelivery, "Same timestamp, preferring server");
- }
- }
- 
- /**
- * Merge delivery data intelligently
- */
- private ConflictResolution<DeliveryEntity> mergeDeliveryData(DeliveryEntity localDelivery, DeliveryEntity serverDelivery) {
- Log.d(TAG, "Merging delivery data for ID: " + localDelivery.getId());
- 
- // Create a new merged delivery
- DeliveryEntity merged = new DeliveryEntity(
- localDelivery.getId(),
- localDelivery.getTripId(),
- localDelivery.getOrderNumber() != null ? localDelivery.getOrderNumber() : "unknown",
- localDelivery.getCustomerName() != null ? localDelivery.getCustomerName() : "unknown",
- localDelivery.getAddress() != null ? localDelivery.getAddress() : "unknown",
- localDelivery.getQuantityExpected()
- );
- 
- // Status: Use the more "progressed" status
- String mergedStatus = mergeStatus(localDelivery.getStatus(), serverDelivery.getStatus());
- merged.setStatus(mergedStatus);
- 
- // Use server data for fields that shouldn't change once set
- merged.setCustomerPhone(serverDelivery.getCustomerPhone() != null ? serverDelivery.getCustomerPhone() : localDelivery.getCustomerPhone());
- merged.setDeliveryInstructions(serverDelivery.getDeliveryInstructions() != null ? serverDelivery.getDeliveryInstructions() : localDelivery.getDeliveryInstructions());
- merged.setEstimatedDeliveryTime(serverDelivery.getEstimatedDeliveryTime() != null ? serverDelivery.getEstimatedDeliveryTime() : localDelivery.getEstimatedDeliveryTime());
- 
- // For delivery-specific fields, prefer the most recent updates
- merged.setActualDeliveryTime(mergeTimestamp(localDelivery.getActualDeliveryTime(), serverDelivery.getActualDeliveryTime()));
- merged.setDeliveryNotes(mergeString(localDelivery.getDeliveryNotes(), serverDelivery.getDeliveryNotes(), 
- localDelivery.getUpdatedAt(), serverDelivery.getUpdatedAt()));
- merged.setProofOfDeliveryPath(mergeString(localDelivery.getProofOfDeliveryPath(), serverDelivery.getProofOfDeliveryPath(),
- localDelivery.getUpdatedAt(), serverDelivery.getUpdatedAt()));
- 
- // Use the latest timestamps
- merged.setCreatedAt(Math.min(localDelivery.getCreatedAt(), serverDelivery.getCreatedAt()));
- merged.setUpdatedAt(Math.max(
- localDelivery.getUpdatedAt() != null ? localDelivery.getUpdatedAt() : localDelivery.getCreatedAt(),
- serverDelivery.getUpdatedAt() != null ? serverDelivery.getUpdatedAt() : serverDelivery.getCreatedAt()
- ));
- 
- // Preserve sync metadata from server
- merged.setServerVersion(serverDelivery.getServerVersion());
- merged.markAsSynced();
- 
- Log.d(TAG, "Delivery merge completed - Status: " + merged.getStatus());
- return ConflictResolution.useMerged(merged, "Data merged from both versions");
- }
- 
- // =================== UTILITY METHODS ===================
- 
- /**
- * Merge status fields, preferring the more progressed status
- */
- private String mergeStatus(String localStatus, String serverStatus) {
- if (localStatus == null) return serverStatus;
- if (serverStatus == null) return localStatus;
- if (localStatus.equals(serverStatus)) return localStatus;
- 
- // Define status progression order
- String[] statusOrder = {"PENDING", "ASSIGNED", "IN_PROGRESS", "DELIVERED", "FAILED", "CANCELLED"};
- 
- int localIndex = getStatusIndex(localStatus, statusOrder);
- int serverIndex = getStatusIndex(serverStatus, statusOrder);
- 
- // Return the status that's further in progression
- if (localIndex > serverIndex) {
- Log.d(TAG, "Local status '" + localStatus + "' is more progressed than server '" + serverStatus + "'");
- return localStatus;
- } else {
- Log.d(TAG, "Server status '" + serverStatus + "' is more progressed than local '" + localStatus + "'");
- return serverStatus;
- }
- }
- 
- private int getStatusIndex(String status, String[] statusOrder) {
- for (int i = 0; i < statusOrder.length; i++) {
- if (statusOrder[i].equals(status)) {
- return i;
- }
- }
- return -1; // Unknown status, treat as least progressed
- }
- 
- /**
- * Merge timestamp fields, preferring non-null values and later timestamps
- */
- private Long mergeTimestamp(Long localTimestamp, Long serverTimestamp) {
- if (localTimestamp == null) return serverTimestamp;
- if (serverTimestamp == null) return localTimestamp;
- 
- // Return the later timestamp
- return Math.max(localTimestamp, serverTimestamp);
- }
- 
- /**
- * Merge string fields based on which version was updated more recently
- */
- private String mergeString(String localValue, String serverValue, Long localUpdated, Long serverUpdated) {
- if (localValue == null) return serverValue;
- if (serverValue == null) return localValue;
- if (localValue.equals(serverValue)) return localValue;
- 
- // If we have update timestamps, use the more recent value
- if (localUpdated != null && serverUpdated != null) {
- return localUpdated > serverUpdated ? localValue : serverValue;
- }
- 
- // Default to server value if no timestamp info
- return serverValue;
- }
- 
- /**
- * Get the default conflict resolution strategy
- * In production, this could be configurable per client or user preference
- */
- public ConflictStrategy getDefaultStrategy() {
- return ConflictStrategy.MERGE; // Prefer intelligent merging
- }
- 
- /**
- * Determine if automatic resolution is possible for the given conflict
- */
- public boolean canAutoResolve(String entityType, ConflictStrategy strategy) {
- // All strategies except USER_CHOICE can be auto-resolved
- return strategy != ConflictStrategy.USER_CHOICE;
- }
- 
- /**
- * Log conflict resolution details for debugging
- */
- private void logResolution(String entityType, String entityId, ConflictStrategy strategy, String resolution) {
- Log.i(TAG, String.format("Conflict resolved - Type: %s, ID: %s, Strategy: %s, Resolution: %s", 
- entityType, entityId, strategy, resolution));
- }
-}

